-- las-aventuras-de-tom-sawyer -- PARTE 2 de 5. Ejecuta las partes EN ORDEN.

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  20,
  'Beck y Tom se encuentran (5/5)',
  $lira$[{"type": "p", "text": "—Déjamelo ver."}, {"type": "p", "text": "Tom le mostró una parte de una horrible caricatura de una casa con dos aleros y un tirabuzón de humo que salía de la chimenea. Entonces el interés de la muchacha se quedó prendado de la obra y se olvidó de todo lo demás. Cuando estuvo terminada, la contempló un instante y musitó:"}, {"type": "p", "text": "—¡Qué bonita! Dibuja un hombre."}, {"type": "p", "text": "El artista erigió un hombre que parecía una grúa en el patio delantero. De una zancada hubiera podido pasar por encima de la casa; pero la chica no era demasiado crítica; se quedó satisfecha con el monstruo y murmuró:"}, {"type": "p", "text": "—Es un hombre estupendo; ahora dibújame a mí paseando."}, {"type": "p", "text": "Tom dibujó un reloj de arena con una luna llena y unos miembros de alambre, y armó los dedos extendidos con un portentoso abanico. La muchacha dijo:"}, {"type": "p", "text": "—¡Es precioso! Me gustaría saber dibujar."}, {"type": "p", "text": "—Es fácil —susurró Tom—; yo te enseñaré."}, {"type": "p", "text": "—¡Oh! ¿De veras? ¿Cuándo?"}, {"type": "p", "text": "—Este mediodía. ¿Vas a tu casa a almorzar?"}, {"type": "p", "text": "—Si tú quieres me quedaré."}, {"type": "p", "text": "—Bien, trato hecho. ¿Cómo te llamas?"}, {"type": "p", "text": "—Becky Thatcher. ¿Y tú? Ah, ya lo sé: Thomas Sawyer."}, {"type": "p", "text": "—Solo me llamo así cuando me zurran. Cuando soy bueno me llamo Tom. Llámame Tom, ¿de acuerdo?"}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "Tom comenzó a garrapatear en la pizarra, ocultando las palabras a la muchacha. Pero esta vez Becky ya no se retraía. Quiso ver qué era. Tom dijo:"}, {"type": "p", "text": "—No es nada."}, {"type": "p", "text": "—Sí, algo es."}, {"type": "p", "text": "—No, no es nada. Tú no quieres verlo."}, {"type": "p", "text": "—Sí quiero, de verdad. ¡Por favor!"}, {"type": "p", "text": "—Lo dirás."}, {"type": "p", "text": "—No lo diré, te lo juro por lo que más quieras."}, {"type": "p", "text": "—¿No se lo dirás a nadie en absoluto? ¿Nunca mientras vivas?"}, {"type": "p", "text": "—No, no se lo diré a nadie. Ahora déjamelo ver."}, {"type": "p", "text": "—Pero ¡si tú no quieres verlo!"}, {"type": "p", "text": "—Pues, bien, ya que me tratas así, lo veré. —Puso su manita sobre la de él y se inició una pequeña contienda. Tom, aunque pretendía resistir en serio, dejó que su mano resbalase poco a poco, hasta que se vieron estas palabras: «Te amo»."}, {"type": "p", "text": "—¡Oh, qué malo eres! —Y le dio un vivo sopapo en la mano, pero enrojeció y pareció complacida, a pesar de todo."}, {"type": "p", "text": "En aquel preciso instante el muchacho sintió una lenta garra fatal que se cerraba sobre su oreja y un firme impulso elevador. De esta guisa fue transportado a través de la sala y depositado en su sitio, bajo un hiriente fuego de risas de toda la escuela. Entonces el maestro permaneció junto a él durante unos pavorosos instantes, y al final se alejó hacia su trono sin decir palabra. Pero aunque a Tom le escocía la oreja, su corazón rebosaba de júbilo."}, {"type": "p", "text": "Mientras la clase se apaciguaba, Tom hizo un honrado esfuerzo por estudiar, pero el tumulto en su cerebro era excesivo. Cuando le tocó el turno en la clase de lectura no dijo más que tonterías; luego, en la clase de geografía convirtió los lagos en montañas, las montañas en ríos y los ríos en continentes, hasta rehacer el caos; más tarde, en la clase de ortografía, una sucesión de palabras infantiles le hizo «morder el polvo», hasta que se vio obligado a entregar la medalla de peltre que había llevado ostentosamente durante varios meses."}]$lira$::jsonb,
  528
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  21,
  'El juego de la garrapata y un corazón que se desgarra (1/3)',
  $lira$[{"type": "p", "text": "Cuanto más se afanaba Tom para concentrarse en el libro, más se le dispersaban las ideas. Al final, con un suspiro y un bostezo, se dio por vencido. Le parecía que el descanso de mediodía no llegaría nunca. El aire estaba absolutamente muerto. No soplaba brisa alguna. Era el día más soñoliento de los días soñolientos. El soporífero murmullo de veinticinco escolares estudiando arrullaba el alma como el sortilegio que existe en el zumbido de las abejas. A lo lejos, en el llameante sol, la colina de Cardiff erguía sus suaves laderas verdes a través de un pálido velo neblinoso que la distancia teñía de púrpura; unos pájaros volaban con perezosas alas en el espacio; no se veía ningún otro ser vivo, salvo unas vacas que estaban dormidas. El corazón de Tom ansiaba libertad, o por lo menos tener algo de interés con que pasar aquel rato espantoso. Su mano anduvo vagando por el bolsillo y su rostro se iluminó con un fulgor de gratitud que era una oración, aunque él no lo supiera. Entonces apareció furtivamente la caja de pistones. Liberó la garrapata y la dejó sobre el largo pupitre liso. La bestezuela resplandeció probablemente con una gratitud que equivalía también a una oración, pero era prematura, pues cuando, agradecida, comenzaba a alejarse, Tom le hizo dar la vuelta con un alfiler y la obligó a tomar una nueva dirección. El amigo íntimo de Tom ocupaba el sitio contiguo; sufría tanto como había sufrido Tom, y enseguida se mostró profunda y gratamente interesado en ese entretenimiento. El amigo íntimo era Joe Harper. Los dos muchachos eran uña y carne toda la semana, y belicosos enemigos los sábados. Joe se sacó un alfiler de la solapa y comenzó a colaborar en el adiestramiento del prisionero. El juego crecía en interés por momentos. Al cabo de poco Tom dijo que el uno estorbaba al otro, y que ninguno de los dos aprovechaba todo el rendimiento de la garrapata. En consecuencia, colocó la pizarra de Joe sobre el pupitre y trazó en medio una raya que iba de arriba abajo."}, {"type": "p", "text": "—Ahora —dijo—, mientras esté en tu campo, puedes moverla a tu antojo sin que yo intervenga; pero si la dejas escapar y entra en el mío, no podrás tocarla mientras yo no la deje cruzar la raya."}, {"type": "p", "text": "—Muy bien, adelante; ya puedes empezar."}, {"type": "p", "text": "La garrapata huyó de Tom y cruzó el ecuador. Joe la hostigó un rato, y luego se escapó y volvió a cruzar la línea. Este cambio de base ocurrió con frecuencia. Mientras un muchacho atormentaba a la garrapata con apasionado interés, el otro la observaba con un interés no menos apasionado. Las dos cabezas estaban unidas e inclinadas sobre la pizarra, y las dos almas muertas para todo lo demás. Por último, la suerte pareció establecerse y quedarse con Joe. La garrapata probó este recurso y el otro y el de más allá, y se puso tan excitada y anhelante como los muchachos, pero una y otra vez, cuando ya tenía la victoria en la mano, por así decirlo, y los dedos de Tom se adelantaban para actuar a su vez, el alfiler de Joe la hacía virar con destreza y la retenía en su campo. Al final Tom ya no pudo resistir. La tentación era demasiado fuerte, así que alargó la mano interviniendo con el alfiler. Joe se sulfuró al instante y dijo en un tono enérgico:"}, {"type": "p", "text": "—Tom, no la toques."}, {"type": "p", "text": "—Solo quiero moverla un poquito."}, {"type": "p", "text": "—No, señor, eso no vale; déjala tranquila."}, {"type": "p", "text": "—Pero ¡si no será mucho rato!"}, {"type": "p", "text": "—Te digo que no la toques."}, {"type": "p", "text": "—¡No quiero!"}, {"type": "p", "text": "—No puedes tocarla, está en mi campo."}, {"type": "p", "text": "—Oye, Joe Harper, ¿de quién es la garrapata?"}, {"type": "p", "text": "—No me importa de quién sea, está en mi campo y no puedes tocarla."}, {"type": "p", "text": "—Pues yo te digo que la tocaré. La garrapata es mía, y haré con ella lo que me dé la gana o moriré. Una tremenda manotada cayó sobre la espalda de Tom, y un duplicado de la misma sobre Joe; y por espacio de dos minutos no cesó de salir polvo de las dos chaquetas, con gran regocijo de toda la clase. Los muchachos habían estado demasiado absortos para darse cuenta del silencio que se extendió por la escuela momentos antes, cuando el maestro atravesó de puntillas la clase y se quedó detrás de ellos. Había observado buena parte del juego antes de contribuir en él con un poco de variedad."}]$lira$::jsonb,
  739
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  22,
  'El juego de la garrapata y un corazón que se desgarra (2/3)',
  $lira$[{"type": "p", "text": "En la pausa de mediodía, Tom voló al lado de Becky Thatcher y le murmuró al oído:"}, {"type": "p", "text": "—Ponte el sombrero y haz ver que te vas a casa; y cuando llegues a la esquina, deja pasar a los demás, atraviesa el camino y vuelve. Yo iré por el otro lado y volveré de la misma manera."}, {"type": "p", "text": "Así, pues, él partió con un grupo de escolares y ella con otro. Poco después se reunieron al final del camino, y cuando llegaron a la escuela pudieron disponer de ella a su antojo. Se sentaron juntos, con una pizarra delante, y Tom le dio a Becky el lápiz y le guió la mano con la suya, creando de este modo otra sorprendente mansión. Cuando empezó a decaer el interés por el arte, se pusieron a charlar. A Tom le parecía estar en la gloria."}, {"type": "p", "text": "—¿Te gustan las ratas? —preguntó."}, {"type": "p", "text": "—¡No! Me dan asco."}, {"type": "p", "text": "—También a mí me dan asco… vivas. Pero yo quiero decir muertas, para hacerlas voltear sobre la cabeza con una guita."}, {"type": "p", "text": "—No, no me interesan mucho las ratas. Lo que me gustan son los chicles."}, {"type": "p", "text": "—¡Claro! Ojalá tuviera alguno ahora."}, {"type": "p", "text": "—¿Quieres? Yo tengo. Te dejaré mascar un ratito, pero luego tienes que devolvérmelo. Aquello era muy agradable, de manera que mascaron por turno y balancearon las piernas desde el banco en un exceso de contento."}, {"type": "p", "text": "—¿Has estado alguna vez en el circo? —preguntó Tom."}, {"type": "p", "text": "—Sí, y papá me llevará otra vez si soy buena."}, {"type": "p", "text": "—Yo he estado en el circo tres o cuatro veces; muchas veces. Aunque es más divertido ir a la iglesia. Allí todo es movimiento. Yo seré payaso de circo cuando sea mayor."}, {"type": "p", "text": "—¿De veras? Será estupendo. ¡Qué bonitos son, con tantos lunares!"}, {"type": "p", "text": "—Sí, es cierto. Y ganan una porrada de dinero; a veces un dólar al día, dice Ben Rogers. Oye, Becky, ¿has estado prometida alguna vez?"}, {"type": "p", "text": "—¿Qué es eso?"}, {"type": "p", "text": "—Pues prometida para casarse."}, {"type": "p", "text": "—No."}, {"type": "p", "text": "—¿Te gustaría?"}, {"type": "p", "text": "—Tal vez. No sé. ¿A qué se parece?"}, {"type": "p", "text": "—¿A qué? No se parece a nada. Solo tienes que decir a un muchacho que le querrás siempre, siempre, siempre, y luego besarlo y ya está. Cualquiera puede hacerlo."}, {"type": "p", "text": "—¿Besarlo? ¿Por qué se ha de besar?"}, {"type": "p", "text": "—Bueno, eso, ¿sabes?, es para… bueno, se hace siempre."}, {"type": "p", "text": "—¿Todo el mundo?"}, {"type": "p", "text": "—Pues claro, todo el mundo que está enamorado. ¿Te acuerdas de lo que escribí en la pizarra?"}, {"type": "p", "text": "—Sí."}, {"type": "p", "text": "—¿Qué era?"}, {"type": "p", "text": "—No te lo diré."}, {"type": "p", "text": "—¿Te lo digo yo?"}, {"type": "p", "text": "—Sí… pero en otra ocasión."}, {"type": "p", "text": "—No, ahora."}, {"type": "p", "text": "—No, ahora no, mañana."}, {"type": "p", "text": "—Oh, no, ahora. Por favor, Becky, te lo diré al oído, te lo diré al oído muy quedo…"}, {"type": "p", "text": "Como Becky vacilaba, Tom interpretó su silencio como un consentimiento, y le rodeó la cintura con el brazo y le susurró aquellas palabras con mucha dulzura, la boca pegada a su oído. Y luego añadió:"}, {"type": "p", "text": "—Ahora me lo tienes que decir tú… del mismo modo."}, {"type": "p", "text": "Ella se resistió unos momentos y después dijo:"}, {"type": "p", "text": "—Vuelve la cara para que no me veas, y entonces te lo diré. Pero no debes contárselo a nadie, ¿me oyes, Tom? No se lo contarás a nadie, ¿me lo prometes?"}, {"type": "p", "text": "—Te lo prometo. Vamos, Becky."}, {"type": "p", "text": "Tom apartó el rostro. Becky se inclinó tímidamente hasta que su aliento agitó los rizos del muchacho, y musitó:"}, {"type": "p", "text": "—¡Te… amo!"}, {"type": "p", "text": "Entonces se alejó corriendo por entre los pupitres y los bancos, perseguida por Tom, y al final se refugió en un rincón, ocultándose la cara con el delantalito blanco. Tom la agarró cerca del cuello y le dijo en un tono suplicante:"}, {"type": "p", "text": "—Ahora, Becky, está todo hecho, todos menos el beso. No temas, no es nada importante. ¡Por favor, Becky! —Y le daba tirones a las manos y al delantal."}, {"type": "p", "text": "Al cabo de poco ella cedió y dejó caer las manos; su rostro, arrebolado por la lucha, se alzó sumiso. Tom besó los labios encendidos y dijo:"}]$lira$::jsonb,
  641
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  23,
  'El juego de la garrapata y un corazón que se desgarra (3/3)',
  $lira$[{"type": "p", "text": "—Ahora ya está, Becky. Y después de esto, ¿sabes?, ya no puedes querer a nadie más que a mí ni te puedes casar con nadie más que conmigo, ¿de acuerdo?"}, {"type": "p", "text": "—Sí, no querré a nadie más que a ti, Tom, y nunca me casaré con nadie más que contigo… y tú tampoco te casarás más que conmigo."}, {"type": "p", "text": "—Esto forma parte del acuerdo. Y siempre que vengas a la escuela y vayas a tu casa, tienes que ir conmigo, cuando nadie mire, y tienes que elegirme a mí, y yo a ti, en las reuniones, porque así se hace cuando se ha dado palabra de matrimonio."}, {"type": "p", "text": "—¡Qué bonito es! No lo había oído nunca."}, {"type": "p", "text": "—Es muy divertido. Si supieras lo que yo y Amy Lawrence…"}, {"type": "p", "text": "Los ojazos de Becky descubrieron a Tom su desatino, y el muchacho se calló confuso."}, {"type": "p", "text": "—¡Ay, Tom! Entonces no es la primera vez que estás prometido…"}, {"type": "p", "text": "La niña se echó a llorar."}, {"type": "p", "text": "—No llores, Becky —suplicó Tom—. Ahora ella ya no me importa."}, {"type": "p", "text": "—Sí que te importa, Tom; ya sabes tú que sí."}, {"type": "p", "text": "Tom trató de rodearle el cuello con el brazo, pero ella lo rechazó, volvió la cara a la pared y siguió llorando. Tom lo intentó de nuevo, murmurando palabras de consuelo, pero fue rechazado otra vez. Entonces, herido en su orgullo, se alejó y salió fuera. Allí estuvo unos momentos, inquieto y desazonado, dirigiendo constantes miradas a la puerta, esperando que ella se arrepintiera y saliera a reunirse con él. Pero Becky no salió. De pronto le acometieron amargos pensamientos y pensó que él tenía la culpa. Sostuvo consigo mismo una dura lucha para obligarse a ceder, y al final se decidió y entró. Becky continuaba inmóvil en el rincón, sollozando con el rostro contra la pared. El corazón de Tom latió con violencia. Se acercó a Becky y se detuvo un instante, sin saber exactamente qué hacer."}, {"type": "p", "text": "—Becky, a mí… a mí solo me importas tú —dijo al fin vacilante."}, {"type": "p", "text": "Solo le contestaron más sollozos."}, {"type": "p", "text": "—Becky —le suplicó—. Becky, ¿no quieres decirme nada?"}, {"type": "p", "text": "Más sollozos."}, {"type": "p", "text": "Tom sacó su joya más preciada, una manecilla de latón procedente de un morillo de chimenea, la puso delante de Becky para que pudiera verla, y dijo:"}, {"type": "p", "text": "—Por favor, Becky, ¿quieres aceptar esto?"}, {"type": "p", "text": "Ella lo echó al suelo de un manotazo. Entonces Tom salió de la sala y se encaminó hacia las montañas, muy lejos, con la intención de no volver a la escuela en todo el día. Enseguida Becky comenzó a recelar. Corrió hacia la puerta; no lo vio; voló al patio de recreo; tampoco estaba allí. Entonces gritó:"}, {"type": "p", "text": "—Tom. Ven aquí, Tom."}, {"type": "p", "text": "Aguzó el oído, pero no llegó ninguna respuesta. No tenía otros compañeros que el silencio y la soledad. Así, pues, se sentó a llorar y a vituperarse a sí misma; y en aquel momento comenzaron a volver los escolares, y Becky tuvo que ocultar sus penas y acallar su corazón herido y resignarse a soportar el calvario de una larga tarde triste y dolorosa, sin nadie entre los extraños que la rodeaban a quien confiar sus aflicciones."}]$lira$::jsonb,
  514
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  24,
  'Un temible pirata en cierne (1/2)',
  $lira$[{"type": "p", "text": "Tom deambuló por los caminos hasta que se hubo alejado por completo de la ruta de regreso de los escolares, y entonces empezó a andar a un paso breve y desmayado. Cruzó un arroyuelo dos o tres veces, a causa de una prevaleciente superstición juvenil, según la cual cruzando agua se burlaban las persecuciones. Media hora más tarde desaparecía por detrás de la mansión Douglas en la colina de Cardiff. El edificio de la escuela se distinguía apenas en el valle lejano, a su espalda. Se adentró en un espeso bosque sin seguir ningún sendero y se sentó en un lugar musgoso bajo un arrogante roble. No soplaba ni la más tenue brisa; el calor del mediodía inerte había acallado hasta los cantos de los pájaros; la naturaleza parecía sumida en un letargo que no interrumpía sonido alguno, salvo el ocasional martilleo lejano del pájaro carpintero, y eso aun parecía acrecentar el penetrante silencio y la sensación de soledad. El alma del muchacho estaba llena de melancolía; sus sentimientos armonizaban felizmente con los alrededores. Estuvo largo rato sentado con los codos sobre las rodillas y la barbilla entre las manos, meditando. Le parecía que la vida, a fin de cuentas, era una molestia, y envidiaba más que a medias a Jimmy Hodges, fallecido recientemente: ¡qué paz debía de hallarse, pensaba, yaciendo, durmiendo y soñando eternamente, con el viento susurrando a través de los árboles y acariciando la hierba y las flores de la tumba, sin más preocupaciones ni sufrimientos! Si tuviera unos antecedentes limpios en la escuela dominical, habría podido partir gustoso y terminar con todo. En cuanto a la muchacha, ¿qué había hecho él? Teniendo las mejores intenciones del mundo, lo había tratado como un perro, exactamente igual que a un perro. Algún día ella lo sentiría, tal vez cuando ya fuese tarde. ¡Ojalá pudiera morirse temporalmente! Pero el elástico corazón de la juventud no puede estar mucho tiempo comprimido en un mismo molde de angustia. Al cabo de poco Tom volvió a preocuparse por los problemas de la vida terrena. ¿Y si volviera la espalda y desapareciera misteriosamente? ¿Y si escapara muy lejos, a desconocidas tierras allende los mares, y no regresara jamás? ¡Cómo se sentiría ella entonces! Volvió a ocurrírsele la idea de ser un payaso, pero solo lo llenó de asco, ya que la frivolidad y las chanzas y el traje de lunares eran una ofensa cuando se introducían en un espíritu que se había elevado al reino augusto y vago del romanticismo. No, sería soldado, y volvería después de largos años, cubierto de cicatrices y de gloria. No, mejor aún, se uniría a los indios y cazaría búfalos y seguiría la senda de la guerra en las montañas y en las vastas llanuras del Lejano Oeste, y en el futuro regresaría convertido en un gran jefe, erizado de plumas, repugnante de pintura, y, con la montura encabritada, aparecería en la escuela dominical una soñolienta mañana de verano dando un alarido de guerra que helaría la sangre, y cauterizaría los ojos de todos sus compañeros con implacable rencor. Pero, no, aún había algo más deslumbrante. Sería un pirata. Eso es. De pronto su porvenir se desplegaba ante él con un esplendor inimaginable. ¡Su nombre llenaría el mundo y haría estremecer a la gente! ¡Cuán gloriosamente surcaría los turbulentos mares con su veloz bajel negro, el Espíritu de la Tormenta, con su espantoso pabellón enarbolado a proa! Y en el cénit de su fama, ¡qué súbita irrupción haría en la vieja aldea, y qué majestuosa entrada en la iglesia, moreno y curtido por los temporales, con su justillo y sus calzas de terciopelo negro, sus botas altas, la faja carmesí, el cinturón erizado de pistolas, a un costado el alfanje enmohecido por el crimen, el sombrero chambergo ladeado con ondeantes plumas, y la bandera negra desplegada con el cráneo y los huesos cruzados! Y, extasiado de orgullo, oiría los rumores: «Es Tom Sawyer el Pirata, el Terror de los mares»."}, {"type": "p", "text": "Sí, estaba decidido; ya había elegido su destino. Huiría de su hogar y se marcharía a la aventura. Partiría a la mañana siguiente. Por tanto, tenía que comenzar a prepararse enseguida. Reuniría todos sus recursos. Se encaminó hacia un tronco podrido que había cerca, y se puso a cavar bajo uno de sus extremos con el cuchillo Barlow. No tardó en tocar madera que sonaba a hueco. Metió la mano y pronunció este conjuro de manera asombrosa:"}, {"type": "p", "text": "—¡Lo que no está aquí que venga! ¡Lo que aquí está que se quede!"}, {"type": "p", "text": "Después rascó la tierra y descubrió una tabla de pino. La levantó y debajo apareció una cavidad simétrica, cuyo fondo y cuyos lados estaban protegidos por finas tablas. En ella había una canica. El asombro de Tom no tuvo límites. Se rascó la cabeza con aire perplejo y exclamó:"}, {"type": "p", "text": "—¡Bueno, esto es asombroso!"}, {"type": "p", "text": "Arrojó bruscamente la canica y se quedó meditabundo. Lo cierto es que acababa de fallarle una de las supersticiones que él y sus camaradas habían considerado siempre infalibles. Si se entierra una canica y luego se descubre el sitio con el conjuro que Tom acababa de usar, se encuentran todas las canicas que uno ha perdido en su vida reunidas allí, por más dispersas que hayan estado. Pero esa fórmula acababa de fallar incontestablemente. El edificio entero de la fe de Tom se sacudió hasta sus cimientos. Había oído hablar más de una vez del éxito de la fórmula, pero nunca de su fracaso. No se le ocurrió que él mismo ya la había puesto en práctica varias veces, pero no había hallado nunca, al cabo de quince días, los escondrijos. Estuvo cavilando un rato y al final concluyó que alguna bruja había intervenido rompiendo el hechizo. Quiso asegurarse, así que recorrió los alrededores hasta encontrar un pequeño lugar arenoso con una depresión en forma de embudo. Se tumbó en el suelo, puso la boca junto al agujero y exclamó:"}]$lira$::jsonb,
  987
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  25,
  'Un temible pirata en cierne (2/2)',
  $lira$[{"type": "p", "text": "—¡Larva de hormiga, larva de hormiga, dime la verdad enseguida!"}, {"type": "p", "text": "La arena empezó a moverse y apareció un insecto negro durante un segundo, que luego desapareció aterrorizado."}, {"type": "p", "text": "—¡No lo dice! Así que fue una bruja. Me lo temía."}, {"type": "p", "text": "Tom ya sabía que era inútil intentar nada contra las brujas, de modo que se rindió desanimado. No obstante, se le ocurrió que, cuando menos, podía recuperar la canica que había arrojado poco antes, así que regresó al lugar anterior y emprendió una paciente búsqueda. No logró encontrarla. Entonces volvió junto a su arquilla y se colocó con cuidado en la misma postura en que estaba cuando tiró la canica, sacó otra del bolsillo y la tiró igual, diciendo:"}, {"type": "p", "text": "—Hermana, ve en busca de tu hermana."}, {"type": "p", "text": "Observó dónde se detenía, y allí se dirigió. Pero debía de haberse quedado corta o de haber ido demasiado lejos; así que lo probó dos veces más. La última repetición tuvo éxito. Las dos estaban a un pie una de la otra."}, {"type": "p", "text": "En aquel preciso instante llegó el tenue sonido de una trompetilla de hojalata por los verdes pasadizos del bosque. Tom se quitó la chaqueta y los pantalones a toda prisa, transformó uno de los tirantes en un cinturón, apartó unos matorrales que había detrás del tronco podrido, descubriendo un arco y una flecha de confección tosca, una espada de hojalata y una trompeta de estaño, y en un instante se apoderó de esos objetos y se alejó saltando con las piernas desnudas y la camisa ondeando al viento. Al cabo de poco se detuvo bajo un inmenso olmo, dio un toque de respuesta, y luego empezó a caminar de puntillas y a dirigir cautelosas miradas a un lado y otro. Dijo precavidamente a una escolta imaginaria:"}, {"type": "p", "text": "—¡Valor, mis valientes soldados! Seguid escondidos hasta que yo dé el golpe."}, {"type": "p", "text": "Poco después hizo su aparición Joe Harper, tan ligeramente vestido y armado tan a conciencia como Tom. Este gritó:"}, {"type": "p", "text": "—¡Alto! ¿Quién anda por el Bosque de Sherwood sin mi permiso?"}, {"type": "p", "text": "—Guy de Guisborne no necesita el permiso de nadie. ¿Quién sois vos que… que…?"}, {"type": "p", "text": "—¿Cómo os atrevéis a usar semejante lenguaje? —dijo Tom apuntándole, pues hablaban «como el libro», de memoria."}, {"type": "p", "text": "—¿Quién sois vos que os atrevéis a usar semejante lenguaje?"}, {"type": "p", "text": "—¿Que quién soy? Robin Hood, como sabrán bien pronto vuestros malditos huesos."}, {"type": "p", "text": "—¿Sois en verdad ese famoso proscrito? Gustoso disputaré con vos el derecho a pasar por este bosque. ¡En guardia!"}, {"type": "p", "text": "Cogieron sus espadas de hojalata abandonando los demás bártulos en el suelo, adoptaron una actitud de desafío, con un pie delante del otro, y comenzaron a luchar grave y concienzudamente. Al cabo de poco Tom dijo:"}, {"type": "p", "text": "—Venga, voto al diablo, ¡con brío!"}, {"type": "p", "text": "Prosiguieron la lucha «con brío», jadeando a causa de los esfuerzos. Poco después Tom gritó:"}, {"type": "p", "text": "—¡Cáete, cáete! ¿Por qué no te caes?"}, {"type": "p", "text": "—No quiero. ¿Por qué no te caes tú? Eres el que ha recibido más golpes."}, {"type": "p", "text": "—¿Y eso qué importa? Yo no puedo caer: el libro no lo dice. El libro dice: «Entonces, con un golpe certero atravesó al pobre Guy de Guisborne». Así que tu obligación es volverte y dejar que te toque en la espalda."}, {"type": "p", "text": "No se podía contradecir semejante autoridad, de modo que Joe se volvió, recibió el golpe y se cayó."}, {"type": "p", "text": "—Ahora —dijo Joe levantándose—, deja que te mate a ti. Es lo justo."}, {"type": "p", "text": "—Pero si no puede ser, no sale en el libro."}, {"type": "p", "text": "—Pues el libro ese es una condenada mezquindad, digo yo."}, {"type": "p", "text": "—Oye, Joe, puedes hacer de fraile Tuck o de Much, el hijo del molinero, y aporrearme con un buen garrote; o yo seré el sheriff de Nottingham y tú Robin Hood un ratito y así podrás matarme. Joe aceptó, de manera que representaron esas aventuras. Luego Tom se convirtió de nuevo en Robin Hood, y por obra de la monja traidora que le destapó la herida se desangró hasta la última gota. Y, por último, Joe, representando una tribu completa de llorosos proscritos, lo llevó a rastras con gran tristeza, puso el arco en sus débiles manos, y Tom dijo: «Donde caiga esta flecha, enterrad al pobre Robin Hood, bajo un árbol del bosque verde». Entonces disparó la flecha y se cayó de espaldas, y hubiese muerto, pero fue a parar sobre unas ortigas y Tom saltó con mucha agilidad para tratarse de un cadáver. Los muchachos se vistieron, escondieron sus pertrechos de guerra y se marcharon lamentando que ya no hubiera proscritos y preguntándose qué pretendía haber hecho la civilización moderna para compensar tal pérdida. Ellos habrían preferido ser proscritos durante un año en el bosque de Sherwood que presidentes de Estados Unidos toda la vida."}]$lira$::jsonb,
  774
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  26,
  'Tragedia en el camposanto (1/3)',
  $lira$[{"type": "p", "text": "Aquella noche, a las nueve y media, Tom y Sid fueron enviados a la cama como de costumbre. Dijeron sus oraciones, y Sid no tardó en dormirse. Tom se mantuvo despierto, lleno de inquietud y de impaciencia. Cuando le pareció que ya debía de estar a punto de clarear, oyó el reloj dar las diez. Era desesperante. Hubiera dado vueltas en la cama como le pedían sus nervios, pero temía despertar a Sid. Continuó inmóvil, pues, con la mirada fija en la oscuridad. Todo estaba pavorosamente quieto. Al cabo de poco, de la quietud comenzaron a surgir ligeros ruidos apenas perceptibles. El tictac del reloj se volvió audible. Viejas vigas empezaron a crujir misteriosamente. A lo lejos rechinó la escalera. Era indudable que corrían fantasmas sueltos. Un rítmico y amortiguado ronquido salió del aposento de la tía Polly. Y luego empezó el monótono chirrido del grillo, tan oculto que ningún ser humano habría podido encontrarlo. Luego la roedura fantasmal de una carcoma en la pared de la cabecera de la cama hizo estremecer a Tom; aquello significaba que los días de alguien estaban contados. A continuación rasgó el aire de la noche el aullido lejano de un perro, contestado por otro aullido más débil a una distancia más remota. Tom sufría una agonía. Al final se sintió satisfecho de que el tiempo hubiera cesado y hubiese comenzado la eternidad; el reloj dio las once, pero él no lo oyó. Y entonces llegó, mezclado con sus sueños a medio formar, un maullido sumamente melancólico. Lo sobresaltó una ventana del vecindario al abrirse. Un grito de «¡Largo de aquí, condenado!» y una botella vacía que se rompió contra la pared posterior del cobertizo de su tía lo despertaron por completo, y un minuto después estaba vestido, fuera de la ventana, y se arrastraba a gatas por el tejado del desván. Maulló con precaución una o dos veces, sin dejar de avanzar, luego saltó al tejado del cobertizo y de allí al suelo. Huckleberry Finn estaba esperándolo con su gato muerto. Los muchachos emprendieron la marcha y desaparecieron en las tinieblas. Media hora más tarde hollaban las altas hierbas del cementerio."}, {"type": "p", "text": "Era un cementerio al estilo anticuado del Oeste. Se encontraba sobre una loma a una milla y media del pueblo. Lo rodeaba una desvencijada valla de tablas, que en algunos lugares se inclinaba hacia el interior, y hacia el exterior el resto de las veces, pero en ninguna parte se mantenía derecha. La hierba y la cizaña habían invadido todo el camposanto. Las viejas tumbas estaban hundidas en el suelo y no había ni una sola lápida; unas tablas de madera redondeadas, todas ellas carcomidas, se bamboleaban sobre los sepulcros, buscando un apoyo sin hallar ninguno. La inscripción «A la memoria de…» se había pintado antaño en ellos, pero en la mayoría ya no era legible ni siquiera valiéndose de una luz. Un airecillo sutil gemía entre los árboles, y Tom temió que fuesen los espíritus de los muertos, que se lamentaban de que turbaran su reposo. Los muchachos hablaron poco, y solo en voz muy queda, pues la hora, el lugar, la solemnidad y el silencio les oprimían el corazón. Hallaron el elevado y reciente montículo que buscaban, y se resguardaron bajo tres grandes olmos que crecían agrupados a unos pies de la tumba. Entonces esperaron en silencio durante un rato que les pareció interminable. El ulular de una distante lechuza era el único sonido que turbaba el silencio. Los pensamientos de Tom se volvieron opresivos. Tuvo que forzarse para hablar."}, {"type": "p", "text": "—Huck, ¿crees que a los muertos les gusta que estemos aquí? —preguntó en un susurro."}, {"type": "p", "text": "—Ojalá lo supiera. Esto es muy solemne, ¿no te parece? —murmuró Huckleberry."}, {"type": "p", "text": "—¡Ya lo creo!"}, {"type": "p", "text": "Hubo una pausa considerable, mientras los muchachos meditaban el asunto para sus adentros. Luego Tom musitó:"}, {"type": "p", "text": "—Oye, Huck, ¿crees que Hoss Williams nos oye hablar?"}, {"type": "p", "text": "—Claro que sí. Al menos, nos oye su espíritu."}, {"type": "p", "text": "—Ojalá le hubiese llamado señor Williams. Pero nunca lo hice con mala intención. Todos le llamaban Hoss."}, {"type": "p", "text": "—Un difunto no puede ser muy exigente respecto a cómo hablan de él, Tom."}, {"type": "p", "text": "Aquellas palabras enfriaron los ánimos, y la conversación volvió a extinguirse."}, {"type": "p", "text": "De pronto Tom agarró a su camarada por el brazo y dijo:"}, {"type": "p", "text": "—¡Chitón!"}, {"type": "p", "text": "—¿Qué pasa?"}, {"type": "p", "text": "Los dos muchachos se abrazaron con el corazón palpitante."}]$lira$::jsonb,
  720
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  27,
  'Tragedia en el camposanto (2/3)',
  $lira$[{"type": "p", "text": "—¡Calla! ¡Ya vuelve! ¿No lo oyes?"}, {"type": "p", "text": "—Yo…"}, {"type": "p", "text": "—¡Ahora! Ya lo has oído."}, {"type": "p", "text": "—Válgame Dios, Tom, eso es que vienen, estoy seguro. ¿Qué podemos hacer?"}, {"type": "p", "text": "—¡Qué sé yo! ¿Crees que nos verán?"}, {"type": "p", "text": "—Ay, Tom, ellos pueden ver en la oscuridad, igual que los gatos. ¡Ojalá no hubiéramos venido!"}, {"type": "p", "text": "—No tengas miedo. No creo que se metan con nosotros. No estamos haciendo ningún daño. Si nos quedamos bien quietos, tal vez ni siquiera se den cuenta de que estamos aquí."}, {"type": "p", "text": "—Lo intentaré, Tom, pero ¡Dios mío!, estoy temblando de pies a cabeza."}, {"type": "p", "text": "—¡Oye!"}, {"type": "p", "text": "Los dos muchachos inclinaron la cabeza al mismo tiempo, conteniendo la respiración. Un amortiguado rumor de voces llegaba del extremo más alejado del camposanto."}, {"type": "p", "text": "—¡Mira! ¿No ves allí? —murmuró Tom—. ¿Qué es?"}, {"type": "p", "text": "—El fuego diabólico. ¡Tom, esto es espantoso!"}, {"type": "p", "text": "Entre las tinieblas se acercaban unas sombras confusas balanceando una vieja linterna de hojalata que proyectaba en el suelo innumerables destellos de luz. Al cabo de poco Huckleberry susurró con un estremecimiento:"}, {"type": "p", "text": "—Son los demonios, estoy seguro. Son tres. ¡Válgame el cielo, Tom, estamos perdidos! ¿Puedes rezar?"}, {"type": "p", "text": "—Lo intentaré, pero no te asustes. No nos harán ningún daño. «Con Dios me acuesto, con Dios me…»."}, {"type": "p", "text": "—¡Chitón!"}, {"type": "p", "text": "—¿Qué pasa, Huck?"}, {"type": "p", "text": "—¡Son hombres! Al menos uno de ellos. Uno tiene la voz del viejo Muff Potter."}, {"type": "p", "text": "—¿Estás seguro?"}, {"type": "p", "text": "—Segurísimo. No te muevas ni hagas ruido. No es lo bastante listo para darse cuenta de que estamos aquí. Probablemente esté borracho, como de costumbre, ¡maldito viejo!"}, {"type": "p", "text": "—Bien, no me moveré. Ahora se paran. No lo encuentran. Vienen de nuevo. Caliente. Frío otra vez. Caliente otra vez. ¡Se queman! Han acertado esta vez. Oye, Huck, conozco otra de las voces; es la del indio Joe."}, {"type": "p", "text": "—Sí, la de ese mestizo asesino. Preferiría mil veces que fueran demonios. ¿A qué habrán venido? Entonces el murmullo se apagó del todo, pues los tres hombres habían llegado a la tumba y se encontraban a unos cuantos pies del escondrijo de los muchachos."}, {"type": "p", "text": "—Es aquí —dijo la tercera voz; y el propietario de la misma alzó la linterna mostrando la faz del joven doctor Robinson."}, {"type": "p", "text": "Potter y el indio Joe llevaban una especie de angarillas que contenían una cuerda y un par de palas. Dejaron su carga en el suelo y empezaron a cavar en la tumba. El doctor colocó la linterna a la cabeza de la tumba y se sentó sobre la hierba con la espalda apoyada contra uno de los olmos. Estaba tan cerca de los chicos que habrían podido tocarlo."}, {"type": "p", "text": "—Deprisa, muchachos —dijo en voz baja—; la luna puede salir de un momento a otro."}, {"type": "p", "text": "Los otros dos gruñeron una respuesta y siguieron cavando. Durante un rato no se oyó más que el murmullo rasposo de las palas desembarazándose de su carga de tierra y piedras. Era muy monótono. Al fin una de las palas dio contra el ataúd con un ruido de madera, y uno o dos minutos después los hombres ya lo habían izado. Arrancaron la tapa, sacaron el cadáver y lo echaron rudamente al suelo. La pálida luna se asomó por detrás de las nubes. Prepararon las angarillas y colocaron en ellas el cuerpo, cubierto con una manta, y lo sujetaron con una cuerda. Acto seguido, Potter sacó un cuchillo de enormes proporciones, cortó el extremo de cuerda que pendía y dijo:"}, {"type": "p", "text": "—Bueno, ya hemos acabado esta condenada tarea. Oiga, matasanos, si no nos da usted otros cinco dólares enseguida, aquí se queda el muerto."}, {"type": "p", "text": "—¡Así se habla! —dijo el indio Joe."}, {"type": "p", "text": "—¿Qué significa eso? —dijo el doctor—. Habéis pedido la paga por adelantado, y ya os la he dado."}, {"type": "p", "text": "—Sí, y aún ha hecho usted más cosas —dijo el indio Joe acercándose al doctor, que se había puesto de pie—. Hace cinco años me echó usted de la cocina de casa de su padre, una noche que fui a pedir algo de comer, y me dijo que yo no estaba allí para nada bueno; y cuando juré que me las pagaría, aunque tardase cien años, su padre me metió en la cárcel por vagabundo. ¿Creía usted que lo había olvidado? Recuerde que tengo sangre india. Y ahora le tengo en mis manos y tiene que pagar, ¿comprende? Mientras pronunciaba estas palabras, amenazaba al doctor con el puño junto a su rostro. Robinson le dio un golpe repentino y tendió al rufián en el suelo. Potter, soltando el cuchillo, exclamó:"}]$lira$::jsonb,
  728
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  28,
  'Tragedia en el camposanto (3/3)',
  $lira$[{"type": "p", "text": "—¡Eh, no toque usted a mi compañero!"}, {"type": "p", "text": "Un instante después agarraba al doctor y los dos hombres luchaban con toda sus fuerzas, pisoteando la hierba y rasgando la tierra con los talones. El indio Joe se puso en pie de un salto con los ojos llameantes de ira, cogió el cuchillo de Potter y empezó a deslizarse felinamente en torno a los combatientes, a la espera de una oportunidad. De pronto el doctor consiguió desasirse, cogió el pesado madero que se erguía en la tumba de Williams y con él dejó a Potter tendido en el suelo. En el mismo instante el mestizo creyó que había llegado el momento oportuno y hundió el cuchillo hasta el mango en el pecho del joven. Este se tambaleó y se desplomó en parte sobre Potter, manchándole de sangre. En aquel preciso momento la nube ocultó el pavoroso espectáculo, y los dos asustados muchachos se alejaron a toda prisa en las tinieblas."}, {"type": "p", "text": "Poco después, cuando la luna emergió de nuevo, el indio Joe se hallaba de pie junto a los dos cuerpos, observándolos. Robinson emitió un murmullo ininteligible, dio una larga boqueada o dos y se quedó inmóvil."}, {"type": "p", "text": "—Ya está liquidada aquella cuenta, ¡maldito seas! —murmuró el mestizo."}, {"type": "p", "text": "A continuación se puso a desvalijar el cadáver. Al acabar, puso el cuchillo fatal en la mano derecha de Potter, que estaba abierta, y se sentó en el ataúd vacío. Transcurrieron tres, cuatro o cinco minutos, y entonces Potter empezó a moverse y a gemir. Su mano se cerró sobre el cuchillo; lo levantó, le echó una ojeada, y lo dejó caer con un estremecimiento. Después se incorporó, apartando de sí el otro cuerpo, lo observó y luego miró a su alrededor con una expresión confusa. Sus ojos se encontraron con los de Joe."}, {"type": "p", "text": "—¡Dios bendito! ¿Qué es esto, Joe? —preguntó."}, {"type": "p", "text": "—Mal negocio —dijo Joe sin moverse—. ¿Por qué lo has hecho?"}, {"type": "p", "text": "—¿Yo? ¡Si yo no he hecho nada!"}, {"type": "p", "text": "—Mira, hablando así no arreglarás las cosas."}, {"type": "p", "text": "Potter se puso a temblar y palideció."}, {"type": "p", "text": "—No creía estar borracho. No tenía que haber bebido esta noche. Pero aún tengo la cabeza confusa… más que cuando hemos empezado. No lo comprendo; apenas me acuerdo de nada. Dime, Joe, de verdad, viejo amigo, ¿lo he hecho yo? Joe, yo no quería… por mi alma y por mi honor, que no tenía la menor intención, Joe. Dime cómo ha sido, Joe. ¡Es horrible…! ¡Y él, tan joven y con tal porvenir!… —Verás, os estabais peleando, y él te ha arreado con el madero tirándote al suelo; luego te has levantado dando traspiés, has agarrado el cuchillo y se lo has clavado justo cuando él te daba otro porrazo… Luego has perdido el conocimiento hasta ahora."}, {"type": "p", "text": "—Yo no sabía lo que hacía. Muera yo en este instante si miento. Todo ha sido por culpa del whisky y de la exaltación, supongo. Yo nunca he utilizado un arma en toda mi vida, Joe. Me he peleado, pero con armas jamás. Prométeme que no lo dirás, Joe; tienes que ser un buen compañero. Siempre te he querido, Joe, y siempre he estado a tu lado. ¿Te acuerdas? No lo dirás, ¿verdad, Joe?"}, {"type": "p", "text": "El desdichado cayó de rodillas ante el desalmado asesino, con las manos unidas en actitud de súplica."}, {"type": "p", "text": "—No, siempre has sido justo y leal conmigo, Muff Potter, y no me volveré contra ti. Vamos, Muff, palabras más honestas no pueden decirse."}, {"type": "p", "text": "—Joe, eres un ángel. Te bendeciré mientras viva. —Y Potter se puso a llorar."}, {"type": "p", "text": "—Bueno, bueno, ya basta. Ahora no es momento de lloriqueos. Tú vete por aquel camino, y yo tomaré este. No pierdas tiempo, y no dejes ningún rastro."}, {"type": "p", "text": "Potter emprendió un trote que enseguida se transformó en carrera. El mestizo lo siguió con los ojos y murmuró:"}, {"type": "p", "text": "—Si tan aturdido está de la paliza y tan borracho del ron como proclama su aspecto, no se acordará del cuchillo hasta que esté tan lejos que tema volver por él a estos lugares. ¡Qué cobarde! Unos minutos más tarde, el doctor asesinado, el cadáver tapado con la manta, el ataúd sin tapa y la tumba abierta se hallaban bajo la inspección de la luna. De nuevo reinaba un silencio absoluto."}]$lira$::jsonb,
  700
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  29,
  'La predicción del perro aullador (1/3)',
  $lira$[{"type": "p", "text": "Los dos muchachos seguían corriendo a toda prisa hacia el pueblo, mudos de horror. De vez en cuando echaban un receloso vistazo hacia atrás, por encima del hombro, como si temieran ser perseguidos. Cada tronco que surgía en su camino les parecía un hombre o un enemigo, y les cortaba el aliento. Al apretar el paso junto a las casas que había a la salida del pueblo, los ladridos de unos perros a los que despertaron parecieron dar alas a sus pies."}, {"type": "p", "text": "—¡Con tal que lleguemos a la vieja curtiduría antes de quedarnos sin fuerzas! —murmuraba Tom respirando con dificultad—. Estoy perdiendo el resuello."}, {"type": "p", "text": "El entrecortado jadeo de Huckleberry fue su única respuesta, y los muchachos clavaron la mirada en la meta de sus esperanzas y se esforzaron por llegar a ella. Fueron avanzando y al final, hombro contra hombro, se lanzaron a través de la puerta abierta y cayeron agradecidos y exhaustos en las sombras protectoras de su interior. Al cabo de poco se apaciguaron los acelerados latidos de sus corazones, y Tom murmuró:"}, {"type": "p", "text": "—Huckleberry, ¿qué crees que resultará de todo esto?"}, {"type": "p", "text": "—Si muere el doctor Robinson, creo que funcionará la horca."}, {"type": "p", "text": "—¿Tú crees?"}, {"type": "p", "text": "—¡Estoy convencido, Tom!"}, {"type": "p", "text": "Tom reflexionó un rato y luego dijo:"}, {"type": "p", "text": "—¿Quién lo dirá? ¿Nosotros?"}, {"type": "p", "text": "—¿Qué demonios dices? Supongamos que ocurriese algo y no colgaran al indio Joe. Un día u otro nos mataría, tan seguro como que estamos aquí."}, {"type": "p", "text": "—Eso mismo pensaba, Huck."}, {"type": "p", "text": "—Si ha de hablar alguien, que lo haga Muff Potter, si es tan estúpido. Suele emborracharse lo suficiente."}, {"type": "p", "text": "Tom no dijo nada; continuó reflexionando. Poco después murmuró:"}, {"type": "p", "text": "—Huck, Muff Potter no lo sabe. ¿Cómo puede decirlo?"}, {"type": "p", "text": "—¿Qué razón hay para que no lo sepa?"}, {"type": "p", "text": "—Porque ha recibido el golpe justo cuando el indio Joe hacía la faena. ¿Crees que ha visto algo? ¿Crees que lo sabe?"}, {"type": "p", "text": "—¡Caracoles! Es verdad, Tom."}, {"type": "p", "text": "—Y además, fíjate bien: puede que el golpe haya acabado con él."}, {"type": "p", "text": "—No, no es probable, Tom. Tenía alcohol en el cuerpo; lo he visto y, además, suele beber siempre. Pues, bien, cuando mi padre está lleno de alcohol, ya podrías aporrearlo con una iglesia que no conseguirías nada. Él mismo lo dice. Así que lo mismo ocurrirá con Muff Potter. Pero si el hombre hubiera estado sereno, tal vez el golpe habría acabado con él."}, {"type": "p", "text": "Tras otro meditativo silencio, Tom dijo:"}, {"type": "p", "text": "—Huck, ¿estás seguro de que podrás callar la boca?"}, {"type": "p", "text": "—Tom, tenemos que callar la boca. Ya lo sabes. A ese demonio de indio le daría lo mismo ahogarnos a nosotros que ahogar a un par de gatos, si contásemos la historia y no le ahorcaran. Mira, Tom, vamos a jurarnos el uno al otro… eso es lo que debemos hacer, jurar que no diremos nada."}, {"type": "p", "text": "—De acuerdo. Es lo mejor que podemos hacer. ¿Juraremos cogiéndonos de las manos?"}, {"type": "p", "text": "—No, eso no cuadra en este caso. No está mal para cosas corrientes y sin importancia, especialmente con las chicas, porque de un modo u otro ellas ceden, y lo descubren todo cuando están en un aprieto; pero en un caso tan tremendo como este, deberíamos escribirlo con sangre."}, {"type": "p", "text": "La naturaleza de Tom aplaudió esta idea. Era profunda, oscura y pavorosa. Recogió del suelo una fina tablilla de pino, sacó del bolsillo un trozo de lápiz y garrapateó estas líneas:"}, {"type": "p", "text": "Huck se quedó admirado de la facilidad con que Tom escribía, así como de la sutilidad de su lenguaje. Al instante se sacó un alfiler de la solapa, y se disponía a pincharse cuando Tom dijo:"}, {"type": "p", "text": "—¡Detente! No hagas eso. Los alfileres son de latón. Podría tener cardenillo."}, {"type": "p", "text": "—¿Qué es cardenillo?"}, {"type": "p", "text": "—Un veneno. Basta con que tragues un poco, y ya verás lo que pasa."}, {"type": "p", "text": "Tom quitó entonces el hilo de una de sus agujas, y se pincharon la yema del dedo pulgar y lo comprimieron hasta que salió una gota de sangre. Después de mucho comprimir, Tom logró firmar con sus iniciales, usando la yema del dedo meñique como pluma. Entonces enseñó a Huckleberry la manera de hacer una «h» y una «f», y el juramento quedó sellado. Enterraron la tablilla junto a la pared, llevando a cabo lúgubres ceremonias y hechizos, y dieron por hecho que las cadenas que les ataban la lengua estaban cerradas y la llave extraviada."}]$lira$::jsonb,
  709
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  30,
  'La predicción del perro aullador (2/3)',
  $lira$[{"type": "p", "text": "Una figura se deslizó furtivamente a través de un boquete al otro extremo del arruinado edificio."}, {"type": "p", "text": "—Tom —susurró Huckleberry—, ¿esto nos impedirá esto hablar… para siempre?"}, {"type": "p", "text": "—Claro que sí. Ocurra lo que ocurra, tenemos que callar. Si no nos moriríamos enseguida, ¿no lo sabes?"}, {"type": "p", "text": "—Sí, eso creo."}, {"type": "p", "text": "Continuaron susurrando durante un rato. Luego un perro inició un prolongado y lúgubre aullido muy cerca de donde se hallaban. Los muchachos se agarraron el uno al otro de repente, angustiados por el miedo."}, {"type": "p", "text": "—¿A quién de nosotros se referirá? —dijo ahogadamente Huck."}, {"type": "p", "text": "—No lo sé. Mira por el boquete. ¡Deprisa!"}, {"type": "p", "text": "—No, ¡hazlo tú, Tom!"}, {"type": "p", "text": "—¡Yo no puedo, Huck!"}, {"type": "p", "text": "—¡Por favor, Tom! ¡Acabo de oírlo otra vez!"}, {"type": "p", "text": "—¡Gracias, Dios mío! —susurró Tom—. Conozco la voz. Es Bull Harbison1."}, {"type": "p", "text": "1 Aquí hay que entender “Bull, el perro del señor Harbison”"}, {"type": "p", "text": "—Menos mal; te digo, Tom, que creía morirme de miedo; y hubiese apostado cualquier cosa a que era un perro extraviado."}, {"type": "p", "text": "Volvieron a oírse los aullidos. La bravura de los muchachos naufragó una vez más."}, {"type": "p", "text": "—¡Cielos! No es Bull Harbison —murmuró Huckleberry—. Ve a verlo, Tom."}, {"type": "p", "text": "Tom, muerto de miedo, acercó los ojos al boquete. El murmullo de su voz era apenas audible cuando dijo:"}, {"type": "p", "text": "—¡Ay, Huck, es un perro extraviado!"}, {"type": "p", "text": "—Deprisa, Tom, deprisa. ¿A quién vendrá a buscar?"}, {"type": "p", "text": "—Creo que a los dos, Huck, puesto que estamos juntos."}, {"type": "p", "text": "—¡Ay, Tom, me parece que estamos perdidos! Creo que no hay error posible sobre el lugar adonde iré. He sido tan malo…"}, {"type": "p", "text": "—Eso es por hacer novillos y todo lo que a uno le dicen que no haga. Habría podido ser bueno, igual que Sid, si lo hubiese intentado, pero no lo intenté, por supuesto. Si salgo con vida de esta, te aseguro que me van a emparedar en la escuela dominical."}, {"type": "p", "text": "Tom empezó a lloriquear."}, {"type": "p", "text": "—¡Malo! —y Huckleberry se puso a lloriquear también—. Vamos, Tom Sawyer, tú eres bueno como un dulce en comparación conmigo. ¡Ay, Dios mío, Dios mío, Dios mío, solo quisiera yo la mitad de tu suerte, Tom!"}, {"type": "p", "text": "Tom se aclaró la garganta y murmuró:"}, {"type": "p", "text": "—Fíjate, Huck. Se ha vuelto de espaldas a nosotros."}, {"type": "p", "text": "—Sí que está de espaldas, diantre. ¿Lo estaba antes?"}, {"type": "p", "text": "—Sí. Pero yo, como un tonto, no me he fijado. Es estupendo, ¿sabes? Y ahora ¿a quién puede referirse? El aullido cesó. Tom aguzó el oído."}, {"type": "p", "text": "—¡Oye! ¿Qué es esto? —murmuró."}, {"type": "p", "text": "—Parece como… como una piara de cerdos. No… Es alguien que ronca, Tom."}, {"type": "p", "text": "—Eso es. ¿De dónde viene, Huck?"}, {"type": "p", "text": "—Me parece que de ahí, en ese extremo. Por lo menos da esta impresión. Papá solía dormir ahí, a veces, junto a los cerdos; pero ¡santo cielo!, cuando él ronca levanta las cosas a su alrededor. Además, creo que no ha vuelto nunca más al pueblo."}, {"type": "p", "text": "El espíritu de aventuras se apoderó una vez más de los muchachos."}, {"type": "p", "text": "—Huck, ¿te atreves a ir tú, si voy yo delante?"}, {"type": "p", "text": "—No me gusta mucho, Tom; supongamos que sea el indio Joe."}, {"type": "p", "text": "Tom se acobardó. Pero de repente la tentación los dominó otra vez y los muchachos acordaron hacer un intento, con la condición de emprender una fuga veloz si los ronquidos cesaban. Avanzaron furtivamente de puntillas, el uno detrás del otro. Cuando llegaron a unos cinco pasos del durmiente, Tom pisó una ramita sin querer y esta se rompió con un chasquido seco. El hombre exhaló un suspiro, se encorvó un poco y el rostro le quedó iluminado por la luz de la luna. Era Muff Potter. Los corazones de los chicos dejaron de latir al moverse el hombre, pero sus temores se desvanecieron enseguida. Salieron de puntillas, atravesando el arruinado refugio, y se pararon a cierta distancia para decirse unas palabras de despedida. ¡Entonces aquel prolongado y lúgubre aullido rasgó otra vez el aire de la noche! Se dieron la vuelta y divisaron el extraño perro a pocos pasos del lugar donde yacía Potter, enfrentándose a él mientras señalaba el cielo con el hocico."}, {"type": "p", "text": "—¡Es a él! —exclamaron los muchachos al unísono."}]$lira$::jsonb,
  663
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  31,
  'La predicción del perro aullador (3/3)',
  $lira$[{"type": "p", "text": "—Mira, Tom, dicen que un perro extraviado se puso a aullar delante de la casa de Johnny Miller alrededor de medianoche, hará cosa de dos semanas; y una chotacabras entró y se posó en la barandilla de la escalera y cantó aquella misma noche; y todavía no se ha muerto nadie."}, {"type": "p", "text": "—Ya lo sé. Y supongamos que nadie se muere. ¿No se cayó Gracie Miller en el fuego del hogar y se hizo unas quemaduras horribles aquel mismo sábado?"}, {"type": "p", "text": "—Sí, pero no ha muerto. Es más, mejora cada día."}, {"type": "p", "text": "—Muy bien, espera y verás. Está perdida, tan perdida como Muff Potter. Eso dicen los negros. Luego se separaron meditabundos. Cuando Tom entró en su dormitorio por la ventana, casi había transcurrido toda la noche. Se desnudó con cautela y se durmió felicitándose a sí mismo de que nadie conociera su escapada. No se dio cuenta de que Sid, el apacible roncador, estaba despierto desde hacía una hora."}, {"type": "p", "text": "Cuando Tom se despertó, Sid ya se había vestido y no estaba en el dormitorio. Había algo en la luz que indicaba que era muy tarde, una sensación en la atmósfera de hora avanzada. Tom se quedó sorprendido. ¿Por qué no lo habían llamado acosándolo hasta que se levantara, como de costumbre? La idea lo llenó de tristes augurios. Se vistió en un periquete y bajó la escalera, sintiéndose fatigado y soñoliento."}, {"type": "p", "text": "La familia aún estaba a la mesa, pero ya había terminado de desayunar. No hubo voz alguna de reprimenda, pero sí miradas de soslayo; reinaba un silencio y un aire de solemnidad que hizo estremecer el corazón del culpable. Se sentó y trató de mostrarse alegre, pero se le hizo cuesta arriba, y entonces dejó que el corazón se le hundiera en las más profundas negruras."}, {"type": "p", "text": "Una vez concluido el desayuno, su tía se lo llevó aparte, y Tom resplandeció casi con la esperanza de que iba a ser azotado; pero no fue así. La tía Polly se echó a llorar y le preguntó cómo podía seguir destrozando de aquel modo su abrumado corazón; y al final le dijo que continuara por aquel camino hasta arruinarse, y que llevara sus viejos cabellos grises a la tumba, pues era inútil que ella intentara nada más. Eso era peor que mil azotainas, y Tom tenía el corazón más dolorido que el cuerpo. Se deshizo en llanto, suplicó perdón, prometió enmendarse repetidas veces y al final recibió permiso para marcharse, pero Tom se daba cuenta de que solo había obtenido un perdón imperfecto y que no había establecido más que una débil confianza."}, {"type": "p", "text": "Se alejó de la augusta presencia con demasiado pesar para sentir deseos de venganza contra Sid, de modo que la fugaz retirada de este último por la puerta trasera fue innecesaria. Emprendió el camino de la escuela melancólico y triste, y aceptó la paliza, junto con Joe Harper, por haber hecho novillos el día anterior, como un hombre cuyo corazón está ocupado por dolores profundos y es indiferente a las bagatelas. Luego se dirigió a su sitio, apoyó los codos en el pupitre y la barbilla entre las manos, y contempló fijamente el muro con la pétrea mirada del sufrimiento que ha llegado al límite extremo y no puede ir más allá. Uno de sus codos se apoyaba contra una sustancia dura. Al cabo de un buen rato cambió de posición, despacio y triste, y cogió aquel objeto con un suspiro. Estaba envuelto en un papel. Lo desenvolvió. Exhaló un largo, dilatado y colosal suspiro, mientras se le desgarraba el corazón. ¡Era su manecilla de latón!"}, {"type": "p", "text": "Era la gota que colmaba el vaso."}]$lira$::jsonb,
  602
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  32,
  'A Tom le remueve la conciencia (1/2)',
  $lira$[{"type": "p", "text": "Poco antes de mediodía todo el pueblo quedó repentinamente electrizado por las pavorosas nuevas. No fue necesario el telégrafo, aun por inventar en aquellos tiempos; las noticias corrieron de boca en boca, de grupo en grupo, de casa en casa, con una rapidez poco menos que telegráfica. El maestro, como es natural, dio fiesta aquella tarde; de lo contrario el pueblo se habría formado una extraña opinión de él. Junto al hombre asesinado se había encontrado un cuchillo manchado de sangre seca, y alguien lo había reconocido como perteneciente a Muff Potter. Y se decía que un ciudadano trasnochador se había tropezado con Potter lavándose en el arroyo entre la una y las dos de la madrugada, y Potter se alejó enseguida. Tales circunstancias eran muy sospechosas, especialmente la de lavarse, cosa poco corriente en Potter. Se decía también que se había registrado todo el pueblo en busca del «asesino» (el público no es lento en la cuestión de examinar pruebas y llegar a un veredicto), pero no se había encontrado. Hombres a caballo habían salido por todos los caminos, en todas direcciones, y el sheriff «confiaba» en que sería capturado antes de la noche."}, {"type": "p", "text": "El pueblo entero se encaminaba hacia el camposanto. La angustia de Tom se desvaneció, y el muchacho se unió a la procesión, no porque no prefiriera mil veces más ir a cualquiera otra parte, sino porque lo atraía una pavorosa e inexplicable fascinación. Una vez que hubo llegado al horrible lugar, escurrió su cuerpecillo entre la multitud y contempló el espeluznante espectáculo. Le parecía que había transcurrido un siglo desde la última vez que estuvo allí. Alguien le pellizcó el brazo. Se volvió, y sus ojos se encontraron con los de Huckleberry. Al instante los dos muchachos miraron en derredor preguntándose si alguien habría observado algo extraño en su mirada. Pero todos hablaban y prestaban atención al horrendo espectáculo que tenían ante los ojos."}, {"type": "p", "text": "—¡Pobre muchacho! ¡Pobre joven! Esto habría de servir de lección a los ladrones de cadáveres. A Muff Potter lo colgarán por esto, si lo atrapan."}, {"type": "p", "text": "Todas las exclamaciones eran parecidas. El ministro dijo:"}, {"type": "p", "text": "—¡Fue un castigo de Dios! En ello se ve Su mano."}, {"type": "p", "text": "Tom se estremeció de pies a cabeza, pues sus ojos acababan de posarse sobre la faz impenetrable del indio Joe. En aquel momento la muchedumbre comenzó a moverse y a empujarse, y algunas voces exclamaron:"}, {"type": "p", "text": "—¡Es él! ¡Es él! ¡Viene por sus propios pasos!"}, {"type": "p", "text": "—¿Quién? ¿Quién? —preguntaron veinte voces."}, {"type": "p", "text": "—¡Muff Potter!"}, {"type": "p", "text": "—Ahora se para. Ahora da media vuelta. ¡No lo dejéis escapar!"}, {"type": "p", "text": "Los hombres encaramados en las ramas de los árboles, por encima de Tom, dijeron que no intentaba escaparse, y que solo se mostraba dudoso y perplejo."}, {"type": "p", "text": "—¡Qué desfachatez! —dijo un espectador—; quería volver a echar un vistazo a su obra, supongo, y no esperaba encontrar compañía."}, {"type": "p", "text": "La multitud se apartó para dejar paso, y apareció el sheriff llevando ostentosamente a Potter del brazo. La cara del desdichado estaba pálida, y sus ojos mostraban el miedo del que era presa. Cuando llegó ante el cadáver se estremeció como un epiléptico, se cubrió el rostro con las manos y estalló en lágrimas."}, {"type": "p", "text": "—Yo no lo hice, amigos —sollozó—; palabra de honor que no lo hice."}, {"type": "p", "text": "—¿Y quién te acusa? —gritó una voz."}, {"type": "p", "text": "Este tiro pareció dar en el blanco. Potter levantó el rostro y miró a su alrededor con una patética desesperación en los ojos. Vio al indio Joe y exclamó:"}, {"type": "p", "text": "—Joe, tú me prometiste que nunca…"}, {"type": "p", "text": "—¿Es tuyo este cuchillo? —Y el sheriff lo colocó ante él."}, {"type": "p", "text": "Potter se habría caído si no le hubiesen sostenido y dejado en el suelo. Entonces dijo:"}, {"type": "p", "text": "—Algo me decía que de no volver por el… —Se estremeció; luego movió su mano inerte con gesto abrumado y dijo—: Joe, cuéntales cómo fue, ahora todo es inútil."}, {"type": "p", "text": "Huckleberry y Tom se quedaron mudos y con la vista fija, y escucharon al embustero de corazón de piedra mientras iba devanando su serena declaración. Esperaban a cada instante que el cielo azul dejara caer sobre su cabeza los rayos de la ira divina, y se extrañaban de que tardara tanto el castigo. Y cuando hubo terminado y siguió vivo y entero, sus vacilantes impulsos de romper el juramento y salvar al pobre borracho traicionado se esfumaron, pues era evidente que aquel descreído se había vendido a Satanás, y habría de ser fatal meterse con la propiedad de semejante poder."}, {"type": "p", "text": "—¿Por qué no has escapado? ¿Por qué has vuelto aquí? —preguntó alguien."}]$lira$::jsonb,
  748
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  33,
  'A Tom le remueve la conciencia (2/2)',
  $lira$[{"type": "p", "text": "—No podía evitarlo… no podía —gimió Potter—. Quería irme lejos, pero era como si algo más fuerte que yo me empujara hacia aquí. —Y rompió a llorar de nuevo."}, {"type": "p", "text": "El indio Joe repitió su declaración, con la misma calma, unos minutos más tarde. Y los muchachos, viendo que los rayos divinos seguían retenidos, se convencieron de que Joe se había vendido al diablo. El asesino se convirtió para ellos en el objeto más calamitosamente interesante que habían contemplado jamás, y no podían apartar los fascinados ojos de su rostro."}, {"type": "p", "text": "Para sus adentros resolvieron vigilarlo durante las noches en que se ofreciese la ocasión, con la esperanza de echar un vistazo a su horrible dueño."}, {"type": "p", "text": "El indio Joe ayudó a levantar el cuerpo de la víctima y a colocarlo en una carreta a fin de transportarlo; y entre la multitud estremecida corrió el murmullo de que la herida sangró un poco. Los muchachos pensaron que esa feliz circunstancia encarrilaría las sospechas por el buen camino; pero quedaron decepcionados, pues más de un espectador observó:"}, {"type": "p", "text": "—Estaba a tres pies de Muff Potter cuando el cadáver ha sangrado."}, {"type": "p", "text": "El pavoroso secreto y los remordimientos de conciencia de Tom le turbaron el sueño durante toda la semana siguiente, y una mañana, a la hora del desayuno, Sid dijo:"}, {"type": "p", "text": "—Tom, das tantas vueltas y hablas tanto mientras duermes que la mitad de las veces me despiertas. Tom palideció y bajó los ojos."}, {"type": "p", "text": "—Mala señal —dijo la tía Polly gravemente—. ¿Qué está cavilando tu cabeza, Tom?"}, {"type": "p", "text": "—Nada. Nada que yo sepa."}, {"type": "p", "text": "Pero la mano del muchacho temblaba tanto que se le vertió el café de la taza."}, {"type": "p", "text": "—¡Y qué cosas tan raras dices! —prosiguió Sid—. Anoche decías «es sangre, es sangre» y lo repetiste no sé cuántas veces. Y dijiste: «No me atormentes así, ya lo diré». ¿Decir qué? ¿Qué tienes que decir? Todo daba vueltas alrededor de Tom. Es imposible suponer lo que hubiera ocurrido entonces, pero por fortuna la preocupación se desvaneció del rostro de la tía Polly, y acudió, sin saberlo, en ayuda de Tom."}, {"type": "p", "text": "—¡Bah! —dijo—. Es ese horrible asesinato. Yo también tengo pesadillas la mayoría de las noches. A veces sueño que lo he cometido yo."}, {"type": "p", "text": "Mary dijo que a ella le sucedía tres cuartos de lo mismo. Sid, al parecer, estaba satisfecho. Tom se retiró de la augusta presencia tan deprisa como pudo, y a partir de entonces se quejó de dolor de muelas y se ató las mandíbulas cada noche. No se enteró nunca de que Sid se quedaba al acecho y a menudo desataba el vendaje, y entonces se apoyaba sobre el codo y escuchaba un buen rato cada vez, volviendo luego a colocar el vendaje en su sitio. La angustia de Tom fue desapareciendo y el dolor de muelas resultó fastidioso y fue descartado. Si Sid llegó a entresacar algo de los confusos murmullos de Tom, lo guardó para sí."}, {"type": "p", "text": "A Tom le parecía que sus compañeros de escuela jamás dejarían de iniciar encuestas sobre gatos muertos, manteniendo así vivo en su pensamiento el desagradable recuerdo. Sid observó que Tom nunca era forense judicial en esas encuestas, aun cuando fuese su costumbre tomar la dirección de toda nueva empresa; observó también que Tom jamás actuaba de testigo, cosa bien rara; y no le pasó por alto el hecho de que Tom mostrase incluso una marcada aversión hacia aquellas encuestas, y las evitara siempre que podía. Sid estaba maravillado, pero no dijo nada. Sin embargo, hasta las encuestas pasaron de moda y cesaron de torturar la conciencia de Tom."}, {"type": "p", "text": "Durante aquella época de dolor, cada uno o dos días Tom buscó la ocasión de acercarse al enrejado ventanuco de la cárcel y procuró al «asesino» todos los pequeños consuelos que pudo reunir. La cárcel era una insignificante madriguera de ladrillo que se alzaba en un aguazal en el extremo del pueblo, a la que no se destinaba guardia alguna; en realidad raras veces estaba ocupada. Aquellos regalitos contribuían mucho a sosegar la conciencia de Tom."}, {"type": "p", "text": "En el pueblo ardían en deseos de apalear y arrastrar al indio Joe por robar cadáveres, pero este tenía tan malas pulgas que, al no encontrar a nadie que quisiera ponerse a la cabeza de tal empresa, fue desechada. Joe había tenido buen cuidado de comenzar sus dos declaraciones con la descripción de la lucha, sin confesar el robo de la tumba que la precedió; en consecuencia, se juzgó lo más prudente no presentar, de momento, el caso a los tribunales."}]$lira$::jsonb,
  748
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  34,
  'El gato y el bálsamo milagroso (1/2)',
  $lira$[{"type": "p", "text": "Una de las razones por las que el pensamiento de Tom se había desviado de sus preocupaciones secretas era que había encontrado una nueva cuestión importante en la que interesarse. Becky Thatcher había dejado de ir a la escuela. Tom había luchado con su orgullo durante unos cuantos días intentando extirpar aquel amor de su corazón, pero había sido en vano. Casi sin darse cuenta se encontró rondando todas las noches la casa del juez, y sintiéndose muy desdichado. Becky estaba enferma. ¿Y si se moría? Este pensamiento le procuró distracción. Ya no sentía interés por la guerra ni siquiera por la piratería. El hechizo de la vida se había evaporado; solo quedaba la melancolía. Abandonó el arco y el palo, pues en ellos ya no hallaba placer. Su tía estaba preocupada. Comenzó a probar toda clase de remedios con él. La tía Polly era de esas personas embobadas por los medicamentos patentados y todos los nuevos métodos para favorecer la salud o remendarla. Era una inveterada experimentadora de tales potingues. Cuando aparecía algún nuevo producto de esta clase, enseguida era presa de la fiebre de probarlo; no en su persona, pues nunca estaba enferma, sino en quienquiera que tuviese a mano. Estaba suscrita a todas las publicaciones de salud y otros timos frenológicos; y la solemne ignorancia de que estaban henchidas era absorbida con deleite por la tía Polly. Todas las estupideces que contenían sobre la ventilación, el modo de acostarse, y cómo levantarse, y qué comer, y qué beber, y cuánto ejercicio hacer, y el estado de ánimo en que había de mantenerse uno y la clase de ropa que había de llevar eran para ella el Evangelio, y jamás se daba cuenta de que las salutíferas publicaciones solían contradecir cuanto habían recomendado el mes anterior. Tenía un alma tan sencilla que resultaba una víctima fácil. Reunía las publicaciones y los medicamentos propios de engañabobos, y, armada de tal guisa contra la muerte, cabalgaba en su pálida montura, metafóricamente hablando, con «el infierno a sus talones». Pero jamás dudó de que no fuese un ángel curativo y el bálsamo de Galaad, disfrazado, para sus vecinos enfermos."}, {"type": "p", "text": "A la sazón el tratamiento del agua era una novedad, y el estado de abatimiento de Tom fue para la tía Polly una fruta madura. Lo hacía salir cada mañana al romper el día, lo obligaba a quedarse de pie en el cobertizo y lo ahogaba con un diluvio de agua fría; entonces lo restregaba con una toalla áspera como una lima, y de este modo lo hacía reaccionar; luego lo envolvía en una sábana mojada y lo tendía bajo unas mantas hasta que le hacía sudar el alma entera y «las manchas amarillas le salían por los poros», como decía Tom."}, {"type": "p", "text": "Con todo, el muchacho estaba cada vez más melancólico, pálido y abatido. La tía añadió baños calientes, baños de asiento, duchas y chapuzones. El chico continuó tétrico como un ataúd. Entonces la tía Polly empezó a combinar el agua con un régimen de harina de avena y vejigatorios. Calculaba la capacidad de Tom como si fuera la de una jarra, y lo llenaba cada día con potingues de charlatán. Tom se mostraba indiferente a la encarnizada persecución. Ese síntoma llenó de consternación el corazón de la anciana. Era preciso romper tal indiferencia a toda costa. Entonces oyó hablar del «bálsamo milagroso» por primera vez. Enseguida hizo un copioso pedido. Lo probó y se sintió llena de gratitud. Era, simplemente, fuego en forma líquida. Abandonó el tratamiento del agua y todos los demás, hincando su fe en el «bálsamo». Dio a Tom una cucharadita de la poción y esperó el resultado con la más profunda ansiedad. Sus inquietudes se calmaron al instante y su alma volvió a conocer la paz, pues la «indiferencia» se había roto. El muchacho no habría podido mostrar un interés más salvaje y más cordial si le hubiesen encendido una hoguera bajo los pies."}, {"type": "p", "text": "Tom se dio cuenta de que ya era hora de reaccionar; aquella clase de vida podía ser todo lo romántica que convenía a su estado de ánimo, pero implicaba demasiada perturbación. En consecuencia, ideó varios planes para aliviarse, y al final se le ocurrió profesar una gran afición al «bálsamo milagroso». Lo pidió con tanta frecuencia que se hizo insoportable, y su tía acabó diciéndole que se lo sirviera él mismo y dejase de molestarla. Si se hubiese tratado de Sid, ningún recelo hubiese empañado su dicha; pero tratándose de Tom, vigiló la botella a escondidas. Descubrió que la medicina disminuía de veras, pero no se le ocurrió que el muchacho estuviera remendando la salud de una grieta en el entablado del salón. Un día Tom estaba ocupado administrando la dosis a la grieta, cuando hizo su aparición el gato amarillo de la tía Polly, ronroneando, echando codiciosas ojeadas a la cucharilla y suplicando una degustación."}, {"type": "p", "text": "—No lo pidas si no lo necesitas, Peter —dijo Tom."}, {"type": "p", "text": "Pero Peter dio a entender que lo necesitaba."}, {"type": "p", "text": "—Es mejor que te asegures."}, {"type": "p", "text": "Peter estaba seguro."}, {"type": "p", "text": "—Bien, me lo has pedido y te lo daré, porque no soy roñoso; pero si después no te gusta, no culpes a nadie más que a ti mismo."}]$lira$::jsonb,
  867
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  35,
  'El gato y el bálsamo milagroso (2/2)',
  $lira$[{"type": "p", "text": "Peter dio su conformidad. En consecuencia, Tom le abrió la boca y vertió el «bálsamo milagroso» garganchón adentro. Peter saltó un par de yardas en el aire, luego profirió un maullido de guerra y comenzó una vertiginosa carrera por el salón, chocando contra los muebles, derribando las macetas de flores, y produciendo un trastorno general. Luego se levantó sobre sus patas traseras, en un frenesí de gozo, con la cabeza sobre la espalda y la voz proclamando su inextinguible felicidad. Después reanudó los destrozos por la sala, sembrando la destrucción y el caos a su paso. La tía Polly entró a tiempo para verle ejecutar algunos dobles saltos mortales, lanzar un poderoso hurra final y desaparecer por la ventana abierta, arrastrando con él cuanto quedaba de las macetas. La anciana estaba petrificada de asombro, mirando por encima de las gafas; Tom estaba echado en el suelo desternillándose de risa."}, {"type": "p", "text": "—Tom, ¿qué le ocurre al gato?"}, {"type": "p", "text": "—No lo sé, tía —dijo ahogadamente Tom."}, {"type": "p", "text": "—No he visto nunca nada igual. ¿Cuál habrá sido la causa de su trastorno?"}, {"type": "p", "text": "—De veras no lo sé, tía Polly; los gatos siempre hacen esas cosas cuando están alegres."}, {"type": "p", "text": "—Conque lo hacen siempre, ¿eh?"}, {"type": "p", "text": "Algo había en aquel tono que impulsó a Tom a mantenerse en guardia."}, {"type": "p", "text": "—Sí, señora. Es decir, eso creo."}, {"type": "p", "text": "—Lo crees, ¿eh?"}, {"type": "p", "text": "—Sí, señora."}, {"type": "p", "text": "La tía Polly se había inclinado hacia el suelo, mientras Tom la observaba con un interés no exento de ansiedad. Demasiado tarde para adivinar su propósito. El mango de la cucharilla soplona era visible bajo la cenefa de la cama. La tía Polly la recogió. Tom retrocedió bajando los ojos. La tía Polly lo levantó por el agarradero usual —la oreja— y le golpeó severamente la cabeza con el dedal."}, {"type": "p", "text": "—Veamos, ¿por qué has tratado así al pobre animalillo, que no puede hablar?"}, {"type": "p", "text": "—Lo he hecho porque me ha dado lástima, porque no tiene ninguna tía."}, {"type": "p", "text": "—¿Que no tiene ninguna tía, grandísimo zote? ¿Qué tiene eso que ver?"}, {"type": "p", "text": "—Mucho. Porque si la hubiese tenido, lo habría abrasado ella misma. Le habría quemado las tripas con la misma falta de sentimientos que si hubiese sido un chico."}, {"type": "p", "text": "La tía Polly sintió una repentina punzada de remordimiento. El hecho se le aparecía bajo una nueva luz; lo que era cruel para un gato podía serlo también para un muchacho. Empezó a ablandarse; se sintió arrepentida. Se le humedecieron los ojos y puso una mano sobre la cabeza de Tom diciendo suavemente:"}, {"type": "p", "text": "—Lo hacía con la mejor intención, Tom. Y, además, a ti te sentó bien."}, {"type": "p", "text": "Tom la miró a los ojos, insinuando un guiño apenas perceptible a través de su gravedad."}, {"type": "p", "text": "—Ya sé que tenía usted la mejor intención, tita, y también la tenía yo con Peter. El bálsamo le ha sentado bien. Nunca le había visto dar tantas volteretas…"}, {"type": "p", "text": "—Vete, Tom, vete antes de que vuelvas a enojarme. Y procura ser bueno y no será menester que tomes ninguna medicina."}, {"type": "p", "text": "Tom llegó a la escuela con antelación. Era cosa notoria que tal hecho extraño sucediera cada día en aquellos últimos tiempos. Tal como solía hacer últimamente, se puso a rondar ante la entrada del patio de recreo, en vez de jugar con sus camaradas. Estaba enfermo, decía él, y era verdad. Aparentaba mirar a un lado y a otro, menos al sitio que realmente miraba, a lo largo del camino. Al cabo de poco apareció Jeff Thatcher, y el rostro de Tom se iluminó. Miró un momento y apartó la vista compungido. Cuando llegó Jeff, Tom le habló y llevó la conversación por sutiles derroteros buscando la ocasión para referirse a Becky, pero el atolondrado muchacho no llegó a picar el anzuelo. Tom continuó vigilando, lleno de esperanzas en cuanto una falda revoloteaba a lo lejos, y odiando a su poseedora al ver que no era la que esperaba. Al final dejaron de aparecer faldas y Tom volvió a hundirse en la melancolía; entró en la escuela vacía y se sentó a sufrir. Entonces otra falda pasó ante la entrada y el corazón de Tom se desbocó. Un instante después se hallaba en el patio aullando, riendo, persiguiendo a los muchachos, saltando por encima de la valla jugándose la vida y las piernas, dando volteretas, aguantándose sobre la cabeza, realizando todas las gestas heroicas que podía concebir, y observando con el rabillo del ojo, entretanto, si Becky se fijaba en él. Pero ella parecía no darse cuenta de nada, no lo miró ni una sola vez. ¿Era posible que no supiese que él estaba allí? Trasladó el campo de sus hazañas a su inmediato vecindario; pasó una y otra vez lanzando alaridos de guerra, le arrebató la gorra a un muchacho y la arrojó con violencia al tejado de la escuela, se dejó caer entre un grupo de chicos, dispersándolos en todas direcciones, y él también se cayó despatarrado a los pies de Becky, derribándola casi, pero ella le volvió la espalda, arrugando la naricita, y Tom oyó que decía:"}, {"type": "p", "text": "—Hay gente que se cree muy lista; siempre está exhibiéndose."}, {"type": "p", "text": "A Tom le ardían las mejillas. Se levantó del suelo y se alejó derrotado."}]$lira$::jsonb,
  854
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  36,
  'Los piratas se hacen a la mar (1/3)',
  $lira$[{"type": "p", "text": "Tom se había decidido. Estaba triste y desesperado. Era un muchacho abandonado, sin amigos, se dijo; nadie lo quería; cuando ellos descubrieran adónde lo habían conducido, tal vez lo lamentasen; él había intentado vivir y obrar de manera recta, pero ellos no se lo habían permitido; puesto que no deseaban más que desembarazarse de él, así sería; podían echarle también la culpa por las consecuencias; ¿por qué no? ¿Qué derecho tiene el desvalido a quejarse? Sí, al final le habían obligado a ello; llevaría una vida de crímenes. No había otra solución."}, {"type": "p", "text": "En aquel momento se encontraba más allá de Meadow Land, y oyó a lo lejos la campana de la escuela anunciando la entrada a clase. Sollozó al pensar que nunca, nunca volvería a oír aquel viejo tañido familiar; era un trance muy duro, pero se lo imponían; puesto que era arrojado al mundo hostil y frío, tenía que someterse, pero los perdonaba a todos. Los sollozos se volvieron más fuertes y persistentes. Precisamente entonces se encontró a su amigo del alma, Joe Harper, con la mirada dura y, era evidente, un grande y lúgubre propósito en el corazón. En pocas palabras, eran «dos almas con un único anhelo». Tom, secándose los ojos con la manga, comenzó a balbucir algo acerca de la resolución de escapar al duro trato y la falta de simpatía de su hogar, y vagar eternamente por el ancho mundo; acabó diciendo que esperaba que Joe no se olvidara de él."}, {"type": "p", "text": "Pero resultó que Joe tenía que hacerle a Tom una petición parecida y que había salido en su busca para tal propósito. Su madre lo había zurrado por comerse un plato de crema que él no había visto siquiera; era evidente que su madre estaba cansada de él y deseaba que se fuera de casa; si esos eran sus sentimientos, a él no le quedaba otro remedio que sucumbir; esperaba que ella fuese feliz, y que nunca lamentase haber arrojado a su pobre hijo a un mundo insensible para que sufriese y muriera en él."}, {"type": "p", "text": "Mientras los dos muchachos caminaban sumidos en la tristeza, hicieron un nuevo pacto de ayuda mutua, de ser hermanos y no separarse jamás hasta que la muerte les aliviase de sus penas. Luego comenzaron a urdir planes. Joe tenía el propósito de hacerse ermitaño y vivir de mendrugos en una cueva remota, y morir, algún día, de frío, de necesidad y de dolor; pero después de escuchar a Tom admitió que una vida de crimen tenía ciertas ventajas, de modo que consintió en ser pirata."}, {"type": "p", "text": "Tres millas más abajo de San Petersburgo, en un punto en que el río Mississippi tenía un poco más de una milla de ancho, había una isla alargada, estrecha y poblada de árboles, con un banco de arena en un extremo que resultaba un lugar ideal para reunirse. No estaba habitada; se extendía ampliamente hacia la orilla más lejana, al nivel de un bosque espeso y despoblado casi por completo. Eligieron la isla de Jackson, como se llamaba, sin vacilaciones. En lo que no pensaron los muchachos fue en quiénes serían las víctimas de sus piraterías. Luego fueron a buscar a Huckleberry Finn, el cual se les unió sin discutir, pues todas las profesiones le daban lo mismo; no tenía preferencia por ninguna. Al cabo de poco se separaron, quedando en encontrarse en un solitario lugar de la orilla del río, dos millas más abajo del pueblo, a su hora favorita, medianoche. En aquel paraje había una pequeña balsa de troncos que se proponían capturar. Cada uno de los muchachos debía traer anzuelos y cordeles y todas las provisiones que pudiera hurtar del modo más lóbrego y misterioso, según corresponde a un proscrito. Antes de que acabara la tarde, todos habían conseguido saborear la dulce gloria de divulgar la nueva de que muy pronto el pueblo «sabría algo». Todo aquel que recibió este vago indicio fue advertido de que «callase y esperara»."}, {"type": "p", "text": "A medianoche Tom llegó con un jamón y algunas otras fruslerías, y se detuvo en un espeso matorral sobre una pequeña elevación que dominaba el lugar de la cita. Las estrellas resplandecían en el cielo y reinaba una calma absoluta. El caudaloso río se extendía como un océano en reposo. Tom escuchó un momento, pero ningún ruido turbó la quietud. Entonces emitió un silbido agudo. Le contestaron desde el pie de la elevación. Tom silbó dos veces más; las señales fueron contestadas del mismo modo. Entonces una voz cautelosa dijo:"}, {"type": "p", "text": "—¿Quién va?"}, {"type": "p", "text": "—Tom Sawyer, la Peste Negra de los Océanos. Decid vuestros nombres."}, {"type": "p", "text": "—Huck Finn, Mano Roja, y Joe Harper, el Terror de los Mares."}, {"type": "p", "text": "Tom les había puesto esos nombres, sacados de sus lecturas favoritas."}, {"type": "p", "text": "—Está bien. Ahora la contraseña."}, {"type": "p", "text": "Dos broncos murmullos pronunciaron a la vez la misma palabra espeluznante:"}, {"type": "p", "text": "—¡Sangre!"}, {"type": "p", "text": "Tom arrojó el jamón desde las alturas, y se dejó caer a su vez, rasgándose un poco la piel y la ropa con el esfuerzo. Había un sendero fácil y cómodo que bordeaba la playa, al pie de la elevación, pero no poseía las ventajas de dificultad y peligro tan estimadas por un pirata."}]$lira$::jsonb,
  855
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  37,
  'Los piratas se hacen a la mar (2/3)',
  $lira$[{"type": "p", "text": "El Terror de los Mares había traído un lomo de cerdo, y casi había echado los bofes al transportarlo. Finn, Mano Roja, había robado una cazuela y cierta cantidad de hojas de tabaco a medio preparar, y había traído también algunas mazorcas de maíz para fabricar pipas. Pero ninguno de los piratas fumaba o mascaba tabaco aparte de él. La Peste Negra de los Océanos dijo que no se podía comenzar sin encender un fuego. Era una idea acertada; las cerillas apenas eran conocidas en aquellos tiempos. Vieron un fuego que humeaba en una gran balsa a unas cien yardas de distancia, y se dirigieron allí furtivamente y se apoderaron de un tizón. Convirtieron aquella empresa en una formidable aventura, diciendo «¡Chis!» a cada instante, y deteniéndose de repente con un dedo en los labios, empuñando dagas imaginarias y ordenando con lóbregos murmullos que si «el enemigo» chistaba, había que «hundirle el puñal hasta el mango», porque «los muertos no hablan». Sabían perfectamente que todos los hombres de la balsa estaban en el pueblo rondando las tiendas o corriéndose una juerga, pero ello no era excusa para no ejecutar la hazaña a la manera pirata."}, {"type": "p", "text": "Se alejaron poco después, Tom al mando de la «nave», Huck en el remo posterior y Joe en el delantero. Tom estaba de pie en medio de la embarcación, con el ceño fruncido y los brazos cruzados, y daba órdenes en tono bajo y severo:"}, {"type": "p", "text": "—¡Orzad, ceñid la nave al viento!"}, {"type": "p", "text": "—Bien, señor."}, {"type": "p", "text": "—¡Firme, fiiirmeee!"}, {"type": "p", "text": "—Ya está, señor."}, {"type": "p", "text": "—Soltadla un poco."}, {"type": "p", "text": "—Hecho, señor."}, {"type": "p", "text": "Como los muchachos conducían la balsa de manera firme y monótona hacia el centro del río, no cabía duda de que Tom daba las órdenes solo para crear ambiente, y que no pretendían significar nada especial."}, {"type": "p", "text": "—¿Qué velas lleva?"}, {"type": "p", "text": "—Las mayores, cofas y foques, señor."}, {"type": "p", "text": "—Izad los juanetes. Y seis de vosotros arriba, ahí, a la cofa de trinquete. ¡Deprisa!"}, {"type": "p", "text": "—Bien, señor."}, {"type": "p", "text": "—Soltad los rizos al juanete del palo mayor. ¡Escotas y brazas! ¡Arriba, muchachos!"}, {"type": "p", "text": "—Enseguida, señor."}, {"type": "p", "text": "—A sotavento, todo a babor. ¡Listos para el encuentro! Puerto, puerto. ¡Adelante, compañeros! ¡Ánimos! Fiiirmeee."}, {"type": "p", "text": "—Firme, señor."}, {"type": "p", "text": "La balsa se hallaba en el centro del río; los muchachos dejaron que la arrastrara la corriente, sirviéndose únicamente de los remos para mantener la dirección. El río no estaba crecido, de modo que no había más de dos o tres millas de corriente. Apenas pronunciaron una palabra durante los tres cuartos de hora siguientes. La balsa pasaba ante el pueblo. Dos o tres luces inciertas indicaban el lugar en que estaba, pacíficamente dormido más allá del ancho río que hacían resplandecer las estrellas, inconsciente de la empresa tremenda que se llevaba a cabo. La Peste Negra seguía con los brazos cruzados, dirigiendo la postrera mirada al escenario de sus primeros gozos y sus últimos pesares, y deseando que «ella» pudiera verle en medio del mar turbulento, enfrentándose con el peligro y la muerte con intrépido corazón, yendo hacia su destino con una torva sonrisa en los labios. Poco su imaginación tuvo que esforzarse para trasladar la isla de Jackson a parajes más alejados del pueblo, de modo que dirigió su «postrera mirada» con el corazón desgarrado y satisfecho. Los demás piratas miraban también por última vez; y se pasaron tanto tiempo mirando que casi dejaron que la corriente los alejase de la isla. Descubrieron el peligro a tiempo y maniobraron para impedirlo. Casi a las dos de la madrugada la balsa tocó tierra en el banco, doscientas yardas más arriba del extremo de la isla, y los chicos lo vadearon varias veces hasta que hubieron desembarcado su cargamento. Entre lo poco que pertenecía a la balsa había una vela vieja que extendieron en un rincón escondido entre los matorrales, formando una especie de tienda para cubrir las provisiones; ellos dormirían al raso mientras durase el buen tiempo, como corresponde a los proscritos. Encendieron un fuego junto a un enorme tronco, en las sombrías profundidades del bosque, y luego frieron un pedazo de beicon en la sartén para cenar, y consumieron la mitad de una torta de maíz que habían traído. Era un juego maravilloso celebrar un festín de aquel modo salvaje y libre, en la selva virgen de una isla desconocida y deshabitada, lejos de los lugares que frecuentaba el hombre, y dijeron que jamás volverían a la civilización. Las verticales llamas iluminaban sus rostros y bañaban con un rojizo fulgor los troncos de los árboles, columnas de aquel templo forestal, haciendo resaltar el brillante follaje y las festoneadas plantas."}, {"type": "p", "text": "Cuando la última loncha de beicon hubo desaparecido y fueron devorados los restos de la torta de maíz, los muchachos se tendieron sobre la hierba, llenos de contento. Podían haber hallado un lugar más fresco, pero no quisieron privarse de un detalle tan romántico como es una fogata de campamento."}, {"type": "p", "text": "—¿No es divertido? —preguntó Joe."}, {"type": "p", "text": "—Es estupendo —dijo Tom—. ¿Qué dirían los chicos si nos vieran?"}]$lira$::jsonb,
  819
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  38,
  'Los piratas se hacen a la mar (3/3)',
  $lira$[{"type": "p", "text": "—¿Qué dirían? Se morirían de miedo si estuviesen aquí, ¿no te parece, Huck?"}, {"type": "p", "text": "—Creo que sí —contestó Huck—; de todos modos, yo estoy muy bien. No necesito nada mejor. Por lo general, no tengo tanto que comer, y aquí no pueden reñirle a uno, ni zurrarle ni echarlo con cajas destempladas."}, {"type": "p", "text": "—Es la vida que a mí me gusta —dijo Tom—. Aquí uno no tiene que levantarse por las mañanas, ni ir a la escuela, ni lavarse, ni hacer todas esas condenadas tonterías. Un pirata no tiene que hacer nada cuando está en tierra, ¿sabes, Joe?, pero un ermitaño tiene que rezar muchísimo, así que no le queda tiempo para divertirse."}, {"type": "p", "text": "—En efecto —dijo Joe—. Eso no se me había ocurrido. Prefiero mucho más ser pirata, ahora que lo he probado."}, {"type": "p", "text": "—Además —añadió Tom—, a la gente no le interesan mucho los ermitaños hoy en día, aunque antaño gozaban de gran favor, pero a un pirata lo respetan siempre. Y un ermitaño tiene que dormir en el sitio más duro que encuentre, y ha de llevar ropas de arpillera y cenizas sobre la cabeza, y estar al raso cuando llueve, y…"}, {"type": "p", "text": "—¿Por qué ha de llevar ropas de arpillera y cenizas sobre la cabeza? —preguntó Huck."}, {"type": "p", "text": "—No lo sé. Pero tiene que hacerlo. Los ermitaños lo hacen siempre. Tú también tendrías que hacerlo si fueras un ermitaño."}, {"type": "p", "text": "—¡Que me ahorquen si lo hiciera! —dijo Huck."}, {"type": "p", "text": "—¿Qué harías entonces?"}, {"type": "p", "text": "—No lo sé. Pero eso te digo que no lo haría."}, {"type": "p", "text": "—Vamos, Huck, tendrías que hacerlo. ¿Cómo podrías evitarlo?"}, {"type": "p", "text": "—Vaya, no lo aguantaría, sencillamente. Me marcharía."}, {"type": "p", "text": "—¡Te marcharías! Valiente ermitaño serías tú. ¡Vaya una calamidad!"}, {"type": "p", "text": "Mano Roja no contestó, pues estaba ocupado en algo mejor. Había acabado de vaciar una mazorca, y la encajó con el tallo de una planta, la cargó de tabaco, aplicó una brasa a la carga y echó una bocanada de humo fragante; gozaba con intensa voluptuosidad. Los otros piratas envidiaban aquel vicio majestuoso, y secretamente resolvieron adquirirlo en breve. Poco después Huck dijo:"}, {"type": "p", "text": "—¿Qué tienen que hacer los piratas?"}, {"type": "p", "text": "—Llevan una vida muy agitada —contestó Tom—; apresan buques y los queman, y cogen el dinero y lo entierran en pavorosos lugares de su isla, donde hay fantasmas y otras cosas que lo vigilan, y matan a todo el mundo en los barcos, haciéndolos pasar por una tabla."}, {"type": "p", "text": "—Y se llevan a las mujeres a la isla —dijo Joe—; a las mujeres no las matan."}, {"type": "p", "text": "—No —confirmó Tom—, a las mujeres no, son demasiado nobles. Y, además, las mujeres siempre son hermosas."}, {"type": "p", "text": "—¡Y no llevan malos trajes! Todos de oro, plata y diamantes —dijo Joe con entusiasmo."}, {"type": "p", "text": "—¿Quién?"}, {"type": "p", "text": "—¿Quién va a ser? Los piratas."}, {"type": "p", "text": "Huck examinó sus ropas con desaliento."}, {"type": "p", "text": "—Creo que no voy vestido de pirata —dijo con cierto patetismo en la voz—; pero no tengo otra ropa. Tom y Joe dijeron que los vestidos suntuosos llegarían muy pronto, en cuanto hubiesen comenzado sus aventuras. Le hicieron comprender que sus pobres harapos bastarían para empezar, aunque los piratas opulentos acostumbraran a dar comienzo a sus aventuras con un guardarropa apropiado. Poco a poco se extinguió la conversación y el sueño invadió los párpados de los pequeños proscritos. La pipa se escurrió de los dedos de Mano Roja, y este se durmió con el sueño de los justos y de los fatigados. Al Terror de los Mares y a la Peste Negra de los Océanos les costó más conciliar el sueño. Dijeron las plegarias para sus adentros, echados en el suelo, pues allí no había nadie con autoridad para obligarlos a que se arrodillaran; en realidad, tenían la intención de no decirlas en absoluto, pero temieron excederse y atraer un posible rayo, especial y súbito, mandado por los cielos. Luego no tardaron en encontrarse en los lindes inminentes del sueño, pero entonces llegó un intruso que no quiso rendirse. Era la conciencia. Empezaron a sentir un vago temor de que habían obrado mal escapándose; después se acordaron de la carne robada y entonces comenzó la verdadera tortura. Intentaron acallarla, recordando a la conciencia que habían hurtado golosinas y manzanas más de veinte veces; pero la conciencia no quería rendirse a tan débiles excusas; al final les pareció que no cabía duda del hecho innegable de que coger golosinas no era más que «birlar», mientras que apoderarse de beicon, jamón y otros comestibles semejantes era pura y simplemente «robar», y en la Biblia había un mandamiento que lo prohibía. En consecuencia, resolvieron en su fuero interno que mientras siguieran en el negocio, sus piraterías no volverían a mancillarse con el crimen del hurto. La conciencia concedió una tregua, y aquellos piratas de curiosa inconsistencia se sumieron en un plácido sueño."}]$lira$::jsonb,
  781
);

insert into public.chapters (book_id, position, title, body, word_count)
values (
  'las-aventuras-de-tom-sawyer',
  39,
  'Los filibusteros acampan felizmente (1/3)',
  $lira$[{"type": "p", "text": "A la mañana siguiente, al despertarse, Tom se preguntó dónde estaba. Se sentó, se frotó los ojos y miró en derredor. Entonces lo comprendió todo. Despuntaba el alba fría y gris, y en la profunda y penetrante calma y el silencio de los bosques había una deliciosa sensación de reposo y paz. No se movía ni una hoja; ni un sonido turbaba la honda meditación de la naturaleza. El rocío había formado rosarios de gotas sobre las hojas y la hierba. Una blanca capa de ceniza cubría el fuego, y una fina espiral de humo azul se alzaba verticalmente en el aire. Joe y Huck aún dormían."}, {"type": "p", "text": "A lo lejos, en el bosque, cantó un pájaro; otro le contestó; luego se oyó el martilleo del pájaro carpintero. Poco a poco la fría opacidad gris de la mañana se volvió más blanca, a la vez que los sonidos se multiplicaban gradualmente y se manifestaba la vida. La maravilla de la naturaleza desperezándose y comenzando su tarea diurna se desplegaba ante el pensativo muchacho. Un gusanillo verde llegó arrastrándose sobre una hoja húmeda, levantando de vez en cuando dos tercios del cuerpo en el aire y oteando a su alrededor para proseguir la marcha, pues estaba inspeccionando el terreno, según pensó Tom; y cuando el gusano se le acercó voluntariamente, Tom se quedó inmóvil como una piedra, mientras sus esperanzas revivían y morían según se le aproximara el bichito o pareciese inclinado a ir a otra parte; y cuando por último caviló durante un penoso momento con su encorvado cuerpecillo en el aire, y entonces se puso a trepar con decisión por la pierna del muchacho y comenzó un viaje por encima de él, el corazón de Tom se alegró, pues aquello significaba que sin duda tendría un traje nuevo, un deslumbrante uniforme de pirata. Luego apareció una procesión de hormigas, procedentes de ninguna parte, y emprendieron sus tareas; una de ellas luchaba vigorosamente con una araña muerta entre los brazos, que era cinco veces mayor que ella, acarreándola, sin desviarse, a lo largo de un tronco. Una mariquita con motas pardas escaló la impresionante cumbre de un tallo de hierba, y Tom se inclinó junto a ella y dijo: «Mariquita, mariquita, vuela pronto a tu casita, que está ardiendo y tus hijitos se encuentran allí solitos», y ella emprendió el vuelo y fue a ver lo que ocurría, lo cual no sorprendió al muchacho, pues ya sabía que aquel insecto era muy crédulo en lo referente a incendios, y más de una vez había puesto a prueba su simplicidad. Luego apareció un escarabajo pelotero empujando obstinadamente su pelota, y Tom tocó la bestezuela para ver cómo encogía las patas contra su cuerpo y fingía estar muerta. Los pájaros promovían a la sazón un regular alboroto. Un tordo, el pájaro burlón del norte, se posó en una rama, encima de la cabeza de Tom, y gorjeó imitando a sus vecinos en un rapto de gozo; luego una chillona corneja descendió, como una llamarada azul, y se detuvo sobre una rama casi al alcance del muchacho, ladeó la cabeza y contempló a los forasteros con ardiente curiosidad; una ardilla gris y un rollizo espécimen de clase raposina pasaron a escondidas, sentándose a intervalos para inspeccionar y charlar con los muchachos, ya que probablemente aquellos seres silvestres jamás habían visto un ser humano y apenas sabían si asustarse o no. Toda la naturaleza ya estaba despierta y en movimiento; el sol perforaba con sus dardos de luz el denso follaje, y un enjambre de mariposas revoloteaba jubilosamente."}, {"type": "p", "text": "Tom despertó a los otros piratas, y se alejaron dando voces. Uno o dos minutos después se habían desnudado y se perseguían y se empujaban unos a otros en el agua límpida y poco profunda del blanco banco de arena. No echaban en falta el pueblecillo dormido en la distancia, más allá de aquel majestuoso derroche de agua. Una corriente vagabunda o una leve crecida del río se había llevado la balsa, pero se alegraron, ya que su desaparición era como quemar el puente que los unía con la civilización. Volvieron al campamento maravillosamente refrescados, alegres y famélicos. El fuego no tardó en llamear de nuevo. Huck encontró un manantial de agua cristalina y fresca, y los muchachos hicieron vasos con hojas de roble y nogal americano, y les pareció que el agua, endulzada con el silvestre hechizo de los bosques, era un sucedáneo bastante aceptable del café. Mientras Joe cortaba las lonchas de beicon para el desayuno, Tom y Huck le dijeron que aguardase un minuto; se dirigieron a un rinconcillo prometedor de la ribera y arrojaron sus anzuelos; encontraron la recompensa casi enseguida. Joe aún no había tenido tiempo de impacientarse, cuando los otros ya estaban de vuelta con algunos hermosos róbalos, un par de percas y un pequeño barbo, víveres suficientes para toda una familia. Frieron el pescado con el beicon y se quedaron asombrados, pues en su vida habían encontrado el pescado tan delicioso. No sabían que el pescado de agua dulce es más sabroso cuanto antes se pone al fuego después de pescarlo; ni habían reflexionado demasiado sobre el formidable aperitivo que significa el dormir al raso, el ejercicio al aire libre y el baño."}]$lira$::jsonb,
  873
);
